screenPanels.initJs:
function(container, apiUrl, tables) {
  // 店舗マスタとその他のテーブルインデックスを特定
  const storeTableIndex = tables.findIndex(t => t.tableName === '店舗マスタ');
  const productTableIndex = tables.findIndex(t => t.tableName === '商品マスタ');
  const predictionTableIndex = tables.findIndex(t => t.tableName === '需要予測結果');
  const salesTableIndex = tables.findIndex(t => t.tableName === '売上実績データ');
  const weatherTableIndex = tables.findIndex(t => t.tableName === '天候データ');
  const eventTableIndex = tables.findIndex(t => t.tableName === 'イベントデータ');

  // DOM要素の取得
  const storeSelect = container.querySelector('#select-store');
  const categorySelect = container.querySelector('#select-category');
  const startDateInput = container.querySelector('#input-start-date');
  const endDateInput = container.querySelector('#input-end-date');
  const seasonalCheck = container.querySelector('#check-seasonal');
  const eventCheck = container.querySelector('#check-event');
  const weatherCheck = container.querySelector('#check-weather');
  const executeBtn = container.querySelector('#btn-execute-prediction');
  const exportBtn = container.querySelector('#btn-export-results');
  const errorMessage = container.querySelector('#error-message');
  const loadingIndicator = container.querySelector('#loading-indicator');
  const resultsArea = container.querySelector('#results-area');
  const predictionChart = container.querySelector('#prediction-chart');
  const comparisonChart = container.querySelector('#comparison-chart');
  const resultsTbody = container.querySelector('#prediction-results-tbody');

  // 店舗データの読み込み
  async function loadStores() {
    if (storeTableIndex >= 0) {
      const stores = await window.aivicApi.list(storeTableIndex);
      if (stores) {
        stores.forEach(store => {
          const option = document.createElement('option');
          option.value = store.id;
          option.textContent = `${store.店舗コード} - ${store.店舗名}`;
          storeSelect.appendChild(option);
        });
      }
    }
  }

  // 予測結果テーブルの再描画
  function renderPredictionResults(results) {
    if (!results || results.length === 0) {
      resultsTbody.innerHTML = '<tr><td colspan="8" style="text-align: center; color: var(--text-muted);">予測結果がありません</td></tr>';
      return;
    }

    resultsTbody.innerHTML = results.map(result => `
      <tr data-id="${result.id}">
        <td>${result.商品コード || '-'}</td>
        <td>${result.商品名 || '-'}</td>
        <td>${result.予測対象日 ? new Date(result.予測対象日).toLocaleDateString() : '-'}</td>
        <td>${result.予測数量 || 0}</td>
        <td>${result.推奨発注数量 || 0}</td>
        <td>${result.予測精度 || 0}%</td>
        <td>
          <span style="padding: 4px 8px; border-radius: 4px; font-size: 12px; 
                       background: ${result.予測ステータス === '完了' ? 'rgba(34, 197, 94, 0.1)' : 'rgba(251, 191, 36, 0.1)'};
                       color: var(--text);">
            ${result.予測ステータス || '未実行'}
          </span>
        </td>
        <td>
          <button class="action-btn secondary detail-btn" data-id="${result.id}">詳細</button>
        </td>
      </tr>
    `).join('');
  }

  // グラフ描画関数
  function drawPredictionChart(data) {
    const canvas = predictionChart;
    const ctx = canvas.getContext('2d');
    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width * devicePixelRatio;
    canvas.height = rect.height * devicePixelRatio;
    ctx.scale(devicePixelRatio, devicePixelRatio);

    const width = rect.width;
    const height = rect.height;
    const padding = 60;

    // 背景をクリア
    ctx.fillStyle = '#1a2332';
    ctx.fillRect(0, 0, width, height);

    if (!data || data.length === 0) {
      ctx.fillStyle = '#9fb0d1';
      ctx.font = '16px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('予測データがありません', width / 2, height / 2);
      return;
    }

    // サンプルデータでグラフを描画
    const maxValue = Math.max(...data.map(d => Math.max(d.actual || 0, d.predicted || 0)));
    const minValue = Math.min(...data.map(d => Math.min(d.actual || 0, d.predicted || 0)));
    const range = maxValue - minValue || 1;

    // 軸を描画
    ctx.strokeStyle = '#4a5568';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, height - padding);
    ctx.lineTo(width - padding, height - padding);
    ctx.stroke();

    // データポイントを描画
    const stepX = (width - padding * 2) / (data.length - 1 || 1);

    // 実績値（青線）
    ctx.strokeStyle = '#3b82f6';
    ctx.lineWidth = 2;
    ctx.beginPath();
    data.forEach((d, i) => {
      const x = padding + i * stepX;
      const y = height - padding - ((d.actual - minValue) / range) * (height - padding * 2);
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    });
    ctx.stroke();

    // 予測値（赤線）
    ctx.strokeStyle = '#ef4444';
    ctx.lineWidth = 2;
    ctx.beginPath();
    data.forEach((d, i) => {
      const x = padding + i * stepX;
      const y = height - padding - ((d.predicted - minValue) / range) * (height - padding * 2);
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    });
    ctx.stroke();

    // 凡例
    ctx.fillStyle = '#3b82f6';
    ctx.fillRect(width - 150, 20, 20, 3);
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '12px sans-serif';
    ctx.fillText('実績値', width - 120, 30);

    ctx.fillStyle = '#ef4444';
    ctx.fillRect(width - 150, 40, 20, 3);
    ctx.fillStyle = '#9fb0d1';
    ctx.fillText('予測値', width - 120, 50);
  }

  // バリデーション関数
  function validateInputs() {
    const errors = [];

    if (!storeSelect.value) {
      errors.push('店舗を選択してください');
    }

    if (!categorySelect.value) {
      errors.push('商品カテゴリを選択してください');
    }

    if (!startDateInput.value) {
      errors.push('予測期間の開始日を設定してください');
    }

    if (!endDateInput.value) {
      errors.push('予測期間の終了日を設定してください');
    }

    if (startDateInput.value && endDateInput.value) {
      const startDate = new Date(startDateInput.value);
      const endDate = new Date(endDateInput.value);
      const today = new Date();
      today.setHours(0, 0, 0, 0);

      if (startDate < today) {
        errors.push('開始日は現在日以降の日付を設定してください');
      }

      if (startDate >= endDate) {
        errors.push('開始日は終了日より前の日付を入力してください');
      }

      const diffDays = (endDate - startDate) / (1000 * 60 * 60 * 24);
      if (diffDays > 365) {
        errors.push('予測期間は最大365日までです');
      }

      if (diffDays < 1) {
        errors.push('予測期間は最低1日以上設定してください');
      }
    }

    if (!seasonalCheck.checked && !eventCheck.checked && !weatherCheck.checked) {
      errors.push('予測モデルを選択してください');
    }

    return errors;
  }

  // エラー表示関数
  function showError(messages) {
    if (messages.length > 0) {
      errorMessage.innerHTML = messages.map(msg => `<div>• ${msg}</div>`).join('');
      errorMessage.classList.remove('hidden');
    } else {
      errorMessage.classList.add('hidden');
    }
  }

  // AI予測実行
  async function executePrediction() {
    const errors = validateInputs();
    if (errors.length > 0) {
      showError(errors);
      return;
    }

    showError([]);
    loadingIndicator.classList.remove('hidden');
    resultsArea.classList.add('hidden');

    try {
      // 予測結果を生成（実際のAI処理のシミュレーション）
      const storeId = storeSelect.value;
      const category = categorySelect.value;
      const startDate = new Date(startDateInput.value);
      const endDate = new Date(endDateInput.value);

      // 模擬的な予測結果データを生成
      const predictionResults = [];
      const sampleProducts = [
        { code: 'P001', name: '商品A' },
        { code: 'P002', name: '商品B' },
        { code: 'P003', name: '商品C' }
      ];

      for (const product of sampleProducts) {
        const predictionData = {
          店舗ID: storeId,
          商品コード: product.code,
          商品名: product.name,
          予測対象日: startDate.toISOString(),
          予測数量: Math.floor(Math.random() * 100) + 50,
          推奨発注数量: Math.floor(Math.random() * 80) + 40,
          予測精度: Math.floor(Math.random() * 30) + 70,
          予測ステータス: '完了',
          予測モデルバージョン: 'v1.0',
          発注済フラグ: false
        };

        if (predictionTableIndex >= 0) {
          const saved = await window.aivicApi.save(predictionTableIndex, predictionData);
          if (saved) predictionResults.push(saved);
        }
      }

      // 結果表示
      setTimeout(() => {
        loadingIndicator.classList.add('hidden');
        resultsArea.classList.remove('hidden');

        // グラフデータの生成
        const chartData = Array.from({length: 7}, (_, i) => ({
          date: new Date(Date.now() + i * 24 * 60 * 60 * 1000),
          actual: Math.floor(Math.random() * 50) + 30,
          predicted: Math.floor(Math.random() * 50) + 35
        }));

        drawPredictionChart(chartData);
        renderPredictionResults(predictionResults);

        // 精度指標の更新
        container.querySelector('#accuracy-score').textContent = '85%';
        container.querySelector('#confidence-interval').textContent = '±12%';
        container.querySelector('#mae-score').textContent = '8.3';

        // 影響要因分析の更新
        container.querySelector('#seasonal-impact').textContent = seasonalCheck.checked ? '中程度' : '考慮なし';
        container.querySelector('#weather-impact').textContent = weatherCheck.checked ? '低' : '考慮なし';
        container.querySelector('#event-impact').textContent = eventCheck.checked ? '高' : '考慮なし';

        // 外部要因情報の更新
        container.querySelector('#weather-forecast').textContent = '晴れ時々曇り';
        container.querySelector('#scheduled-events').textContent = 'セール期間中';

      }, 2000);

    } catch (error) {
      loadingIndicator.classList.add('hidden');
      showError(['予測処理中にエラーが発生しました: ' + error.message]);
    }
  }

  // CSVエクスポート
  async function exportResults() {
    if (predictionTableIndex >= 0) {
      const results = await window.aivicApi.list(predictionTableIndex);
      if (results && results.length > 0) {
        const headers = ['商品コード', '商品名', '予測対象日', '予測数量', '推奨発注数量', '予測精度', 'ステータス'];
        const csvContent = '\uFEFF' + headers.join(',') + '\n' + 
          results.map(r => [
            r.商品コード || '',
            r.商品名 || '',
            r.予測対象日 ? new Date(r.予測対象日).toLocaleDateString() : '',
            r.予測数量 || 0,
            r.推奨発注数量 || 0,
            (r.予測精度 || 0) + '%',
            r.予測ステータス || ''
          ].map(field => `"${field}"`).join(',')).join('\n');

        const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
        const link = document.createElement('a');
        link.href = URL.createObjectURL(blob);
        link.download = `需要予測結果_${new Date().toISOString().split('T')[0]}.csv`;
        link.click();
      } else {
        showError(['エクスポートする予測結果がありません']);
      }
    }
  }

  // イベントリスナーの設定
  executeBtn.addEventListener('click', executePrediction);
  exportBtn.addEventListener('click', exportResults);

  // 行レベル操作のイベントデリゲーション
  container.addEventListener('click', async (e) => {
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      const id = detailBtn.dataset.id;
      // 詳細画面への遷移（AI需要予測処理画面）
      window.showScreen('scr-1778591885672');
    }
  });

  // 初期化処理
  loadStores();

  // デフォルト日付の設定
  const today = new Date();
  const tomorrow = new Date(today);
  tomorrow.setDate(tomorrow.getDate() + 1);
  const nextWeek = new Date(today);
  nextWeek.setDate(nextWeek.getDate() + 7);

  startDateInput.value = tomorrow.toISOString().split('T')[0];
  endDateInput.value = nextWeek.toISOString().split('T')[0];

  // 初期データの表示
  if (predictionTableIndex >= 0) {
    renderPredictionResults(tables[predictionTableIndex].records || []);
  }
}

function(container, apiUrl, tables) {
  let currentProducts = [];
  let currentStores = [];
  let currentPredictions = [];
  let selectedOrders = [];

  // テーブル再描画関数
  function renderProducts(products) {
    const tbody = container.querySelector("#product-tbody");
    if (!products || products.length === 0) {
      tbody.innerHTML = '<tr><td colspan="10" style="text-align: center; color: var(--text-muted); padding: 40px;">商品データがありません</td></tr>';
      return;
    }

    tbody.innerHTML = products.map(product => {
      const prediction = currentPredictions.find(p => p.商品ID === product.商品ID) || {};
      const currentStock = Math.floor(Math.random() * 100) + 10; // 仮の在庫数
      const predictedDemand = prediction.予測数量 || Math.floor(Math.random() * 50) + 5;
      const recommendedOrder = Math.max(0, predictedDemand - currentStock);

      return `
        <tr data-id="${product.商品ID}">
          <td><input type="checkbox" class="order-checkbox" data-product-id="${product.商品ID}"></td>
          <td>${product.商品コード || ""}</td>
          <td>${product.商品名 || ""}</td>
          <td><span class="category-badge" style="padding: 2px 8px; border-radius: 12px; font-size: 12px; background: var(--primary); color: white;">${product.商品カテゴリ || "未分類"}</span></td>
          <td style="text-align: right;">${currentStock}</td>
          <td style="text-align: right; color: var(--primary);">${predictedDemand}</td>
          <td style="text-align: right; font-weight: bold;">${recommendedOrder}</td>
          <td><input type="number" class="input order-quantity" data-product-id="${product.商品ID}" value="${recommendedOrder}" min="0" style="width: 80px;"></td>
          <td><input type="text" class="input order-reason" data-product-id="${product.商品ID}" placeholder="発注理由" style="width: 120px;"></td>
          <td>
            <button class="action-btn secondary adjust-btn" data-product-id="${product.商品ID}" data-recommended="${recommendedOrder}">調整</button>
            <button class="action-btn order-single-btn" data-product-id="${product.商品ID}">発注</button>
          </td>
        </tr>
      `;
    }).join("");
  }

  // 店舗選択肢を設定
  function loadStores() {
    window.aivicApi.list(1).then(stores => {
      if (stores) {
        currentStores = stores;
        const storeSelect = container.querySelector("#select-store");
        storeSelect.innerHTML = '<option value="">店舗を選択してください</option>' +
          stores.map(store => `<option value="${store.店舗ID}">${store.店舗名}</option>`).join("");
      }
    });
  }

  // 需要予測結果を表示
  function displayPredictions(storeId) {
    if (!storeId) {
      container.querySelector("#prediction-area").innerHTML = "店舗を選択すると需要予測結果が表示されます";
      return;
    }

    window.aivicApi.list(8).then(predictions => {
      if (predictions) {
        const storePredictions = predictions.filter(p => p.店舗ID === storeId);
        currentPredictions = storePredictions;

        if (storePredictions.length > 0) {
          const totalPrediction = storePredictions.reduce((sum, p) => sum + (p.予測数量 || 0), 0);
          const avgAccuracy = storePredictions.reduce((sum, p) => sum + (p.予測精度 || 0), 0) / storePredictions.length;

          container.querySelector("#prediction-area").innerHTML = `
            <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 16px; text-align: center;">
              <div>
                <div style="font-size: 24px; font-weight: bold; color: var(--primary);">${totalPrediction}</div>
                <div style="color: var(--text-muted);">総予測需要量</div>
              </div>
              <div>
                <div style="font-size: 24px; font-weight: bold; color: var(--primary);">${Math.round(avgAccuracy)}%</div>
                <div style="color: var(--text-muted);">平均予測精度</div>
              </div>
              <div>
                <div style="font-size: 24px; font-weight: bold; color: var(--primary);">${storePredictions.length}</div>
                <div style="color: var(--text-muted);">予測対象商品数</div>
              </div>
            </div>
          `;
        } else {
          container.querySelector("#prediction-area").innerHTML = "選択した店舗の需要予測データがありません";
        }
      }
    });
  }

  // 初期データ読み込み
  loadStores();
  window.aivicApi.list(2).then(products => {
    if (products) {
      currentProducts = products;
      // 店舗未選択時は商品一覧を表示しない
      container.querySelector("#product-tbody").innerHTML = '<tr><td colspan="10" style="text-align: center; color: var(--text-muted); padding: 40px;">店舗を選択してください</td></tr>';
    }
  });

  // 店舗選択イベント
  container.querySelector("#select-store").addEventListener("change", (e) => {
    const storeId = e.target.value;
    if (storeId) {
      displayPredictions(storeId);
      renderProducts(currentProducts);
    } else {
      container.querySelector("#prediction-area").innerHTML = "店舗を選択すると需要予測結果が表示されます";
      container.querySelector("#product-tbody").innerHTML = '<tr><td colspan="10" style="text-align: center; color: var(--text-muted); padding: 40px;">店舗を選択してください</td></tr>';
    }
  });

  // 検索ボタン
  container.querySelector("#btn-search").addEventListener("click", () => {
    const storeId = container.querySelector("#select-store").value;
    const category = container.querySelector("#select-category").value;
    const dateStart = container.querySelector("#input-date-start").value;
    const dateEnd = container.querySelector("#input-date-end").value;
    const searchText = container.querySelector("#input-search").value.toLowerCase();

    if (!storeId) {
      alert("店舗を選択してください");
      return;
    }

    // 日付範囲チェック
    if (dateStart && dateEnd && new Date(dateStart) > new Date(dateEnd)) {
      alert("終了日は開始日以降の日付を入力してください");
      return;
    }

    window.aivicApi.list(2).then(products => {
      if (products) {
        let filtered = products;

        // カテゴリフィルター
        if (category) {
          filtered = filtered.filter(p => p.商品カテゴリ === category);
        }

        // 商品名検索
        if (searchText) {
          filtered = filtered.filter(p => 
            (p.商品名 || "").toLowerCase().includes(searchText) ||
            (p.商品コード || "").toLowerCase().includes(searchText)
          );
        }

        currentProducts = filtered;
        renderProducts(filtered);

        if (filtered.length === 0 && searchText) {
          container.querySelector("#product-tbody").innerHTML = '<tr><td colspan="10" style="text-align: center; color: var(--text-muted); padding: 40px;">該当する商品が見つかりません</td></tr>';
        }
      }
    });
  });

  // 発注量調整ボタン
  container.addEventListener("click", (e) => {
    const adjustBtn = e.target.closest(".adjust-btn");
    if (adjustBtn) {
      const productId = adjustBtn.dataset.productId;
      const recommended = parseInt(adjustBtn.dataset.recommended);
      const quantityInput = container.querySelector(`input.order-quantity[data-product-id="${productId}"]`);

      const newQuantity = prompt(`推奨発注量: ${recommended}\n新しい発注量を入力してください:`, quantityInput.value);
      if (newQuantity !== null) {
        const qty = parseInt(newQuantity);
        if (isNaN(qty) || qty < 0) {
          alert("発注量は0以上の数値を入力してください");
          return;
        }
        quantityInput.value = qty;
      }
    }

    // 個別発注ボタン
    const orderBtn = e.target.closest(".order-single-btn");
    if (orderBtn) {
      const productId = orderBtn.dataset.productId;
      const product = currentProducts.find(p => p.商品ID === productId);
      const quantityInput = container.querySelector(`input.order-quantity[data-product-id="${productId}"]`);
      const reasonInput = container.querySelector(`input.order-reason[data-product-id="${productId}"]`);

      const quantity = parseInt(quantityInput.value);
      if (isNaN(quantity) || quantity <= 0) {
        alert("発注量は正の数値を入力してください");
        return;
      }

      const storeId = container.querySelector("#select-store").value;
      if (!storeId) {
        alert("店舗を選択してください");
        return;
      }

      // 発注確認モーダル表示
      showOrderModal([{
        productId,
        productName: product.商品名,
        productCode: product.商品コード,
        quantity,
        reason: reasonInput.value
      }]);
    }
  });

  // 一括発注ボタン
  container.querySelector("#btn-bulk-order").addEventListener("click", () => {
    const checkboxes = container.querySelectorAll(".order-checkbox:checked");
    if (checkboxes.length === 0) {
      alert("発注する商品を選択してください");
      return;
    }

    const storeId = container.querySelector("#select-store").value;
    if (!storeId) {
      alert("店舗を選択してください");
      return;
    }

    const orders = [];
    let hasError = false;

    checkboxes.forEach(checkbox => {
      const productId = checkbox.dataset.productId;
      const product = currentProducts.find(p => p.商品ID === productId);
      const quantityInput = container.querySelector(`input.order-quantity[data-product-id="${productId}"]`);
      const reasonInput = container.querySelector(`input.order-reason[data-product-id="${productId}"]`);

      const quantity = parseInt(quantityInput.value);
      if (isNaN(quantity) || quantity <= 0) {
        alert(`${product.商品名}の発注量が正しくありません`);
        hasError = true;
        return;
      }

      orders.push({
        productId,
        productName: product.商品名,
        productCode: product.商品コード,
        quantity,
        reason: reasonInput.value
      });
    });

    if (!hasError && orders.length > 0) {
      showOrderModal(orders);
    }
  });

  // 発注確認モーダル表示
  function showOrderModal(orders) {
    const modal = container.querySelector("#order-modal");
    const details = container.querySelector("#order-details");

    selectedOrders = orders;

    details.innerHTML = `
      <div style="margin-bottom: 16px;">
        <strong>発注内容確認</strong>
      </div>
      ${orders.map(order => `
