        const link = document.createElement("a");
        link.href = URL.createObjectURL(blob);
        link.download = "order_export.csv";
        link.click();
      }
    });
  });

  // ダッシュボード遷移
  container.querySelector("#btn-dashboard").addEventListener("click", () => {
    window.showScreen("scr-1778591780173");
  });
}

function(container, apiUrl, tables) {
  const logTableBody = container.querySelector('#log-table-body');
  const logDetailModal = container.querySelector('#log-detail-modal');
  const alertSettingsModal = container.querySelector('#alert-settings-modal');
  const errorIndicator = container.querySelector('#error-indicator');

  let autoUpdateInterval = null;
  let currentLogs = [];

  // ステータス表示用の関数
  function getStatusBadge(status) {
    const statusMap = {
      '成功': { color: '#28a745', text: '成功' },
      '失敗': { color: '#dc3545', text: '失敗' },
      '実行中': { color: '#ffc107', text: '実行中' },
      '警告': { color: '#fd7e14', text: '警告' }
    };
    const config = statusMap[status] || { color: '#6c757d', text: status };
    return `<span style="background: ${config.color}; color: white; padding: 2px 8px; border-radius: 12px; font-size: 12px;">${config.text}</span>`;
  }

  // ログ一覧の再描画
  function renderLogs(logs) {
    currentLogs = logs;
    logTableBody.innerHTML = logs.map(log => `
      <tr data-id="${log.ログID || log.id}">
        <td>${log.収集開始日時 ? new Date(log.収集開始日時).toLocaleString() : '-'}</td>
        <td>${log.データ種別 || '-'}</td>
        <td>${log.データソース || '-'}</td>
        <td>${log.店舗ID || '-'}</td>
        <td>${getStatusBadge(log.処理ステータス || '不明')}</td>
        <td>${log.収集件数 || 0}</td>
        <td>${log.エラー件数 || 0}</td>
        <td>${log.処理時間秒 || 0}秒</td>
        <td>${log.データ品質スコア || '-'}</td>
        <td>
          <button class="action-btn secondary detail-btn" data-id="${log.ログID || log.id}">詳細</button>
          ${(log.処理ステータス === '失敗' || log.エラー件数 > 0) ? 
            `<button class="action-btn retry-btn" data-id="${log.ログID || log.id}">再実行</button>` : ''}
        </td>
      </tr>
    `).join('');

    updateSummary(logs);
    updateErrorIndicator(logs);
  }

  // サマリー情報の更新
  function updateSummary(logs) {
    const total = logs.reduce((sum, log) => sum + (log.収集件数 || 0), 0);
    const success = logs.filter(log => log.処理ステータス === '成功').length;
    const error = logs.filter(log => log.処理ステータス === '失敗').length;
    const lastRun = logs.length > 0 ? 
      new Date(Math.max(...logs.map(log => new Date(log.収集開始日時 || 0)))).toLocaleString() : '-';

    container.querySelector('#summary-total').textContent = total;
    container.querySelector('#summary-success').textContent = success;
    container.querySelector('#summary-error').textContent = error;
    container.querySelector('#summary-last-run').textContent = lastRun;
  }

  // エラーインジケーターの更新
  function updateErrorIndicator(logs) {
    const errorLogs = logs.filter(log => log.処理ステータス === '失敗' || log.エラー件数 > 0);
    if (errorLogs.length > 0) {
      errorIndicator.classList.remove('hidden');
      container.querySelector('#error-details').textContent = 
        `${errorLogs.length}件のエラーが発生しています。最新エラー: ${errorLogs[0].エラーメッセージ || '詳細不明'}`;
    } else {
      errorIndicator.classList.add('hidden');
    }
  }

  // 初期データの読み込みと描画
  window.aivicApi.list(11).then(logs => {
    if (logs) {
      renderLogs(logs);
    }
  });

  // 検索・絞り込み
  container.querySelector('#btn-search').addEventListener('click', async () => {
    const dataSource = container.querySelector('#select-data-source').value;
    const logLevel = container.querySelector('#select-log-level').value;
    const startDate = container.querySelector('#input-start-date').value;
    const endDate = container.querySelector('#input-end-date').value;

    // 日付範囲の検証
    if (startDate && endDate && new Date(startDate) > new Date(endDate)) {
      alert('開始日は終了日より前の日付を設定してください');
      return;
    }

    try {
      const logs = await window.aivicApi.list(11);
      if (!logs) return;

      let filteredLogs = logs.filter(log => {
        if (dataSource && log.データソース !== dataSource) return false;
        if (logLevel && !log.エラーメッセージ?.includes(logLevel)) return false;
        if (startDate && new Date(log.収集開始日時) < new Date(startDate)) return false;
        if (endDate && new Date(log.収集開始日時) > new Date(endDate)) return false;
        return true;
      });

      renderLogs(filteredLogs);
    } catch (error) {
      alert('検索処理でエラーが発生しました');
    }
  });

  // CSVエクスポート
  container.querySelector('#btn-export').addEventListener('click', async () => {
    try {
      const logs = await window.aivicApi.list(11);
      if (!logs) {
        alert('ログエクスポート処理が失敗しました');
        return;
      }

      const headers = ['収集日時', 'データ種別', 'データソース', '店舗ID', 'ステータス', '収集件数', 'エラー件数', '処理時間', '品質スコア', 'エラーメッセージ'];
      const csvContent = '\uFEFF' + [
        headers.join(','),
        ...logs.map(log => [
          log.収集開始日時 || '',
          log.データ種別 || '',
          log.データソース || '',
          log.店舗ID || '',
          log.処理ステータス || '',
          log.収集件数 || 0,
          log.エラー件数 || 0,
          log.処理時間秒 || 0,
          log.データ品質スコア || '',
          `"${(log.エラーメッセージ || '').replace(/"/g, '""')}"`
        ].join(','))
      ].join('\n');

      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `data_collection_logs_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();
    } catch (error) {
      alert('ログエクスポート処理が失敗しました');
    }
  });

  // 自動更新設定
  container.querySelector('#toggle-auto-update').addEventListener('change', (e) => {
    if (e.target.checked) {
      autoUpdateInterval = setInterval(async () => {
        const logs = await window.aivicApi.list(11);
        if (logs) renderLogs(logs);
      }, 30000); // 30秒間隔
    } else {
      if (autoUpdateInterval) {
        clearInterval(autoUpdateInterval);
        autoUpdateInterval = null;
      }
    }
  });

  // アラート通知設定
  container.querySelector('#btn-alert-settings').addEventListener('click', () => {
    alertSettingsModal.classList.remove('hidden');
  });

  container.querySelector('#btn-close-alert-modal').addEventListener('click', () => {
    alertSettingsModal.classList.add('hidden');
  });

  container.querySelector('#btn-cancel-alert-settings').addEventListener('click', () => {
    alertSettingsModal.classList.add('hidden');
  });

  container.querySelector('#btn-save-alert-settings').addEventListener('click', () => {
    const email = container.querySelector('#alert-email').value;
    const threshold = container.querySelector('#alert-threshold').value;
    const enabled = container.querySelector('#alert-enabled').checked;

    // 設定保存処理（実際の実装では設定テーブルに保存）
    alert('アラート通知設定を保存しました');
    alertSettingsModal.classList.add('hidden');
  });

  // イベントデリゲーション（詳細表示・再実行）
  container.addEventListener('click', async (e) => {
    // 詳細表示
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      const logId = detailBtn.dataset.id;
      const log = currentLogs.find(l => (l.ログID || l.id) === logId);
      if (log) {
        container.querySelector('#log-detail-content').innerHTML = `
          <div style="display: grid; gap: 15px;">
            <div><strong>ログID:</strong> ${log.ログID || log.id}</div>
            <div><strong>データ種別:</strong> ${log.データ種別 || '-'}</div>
            <div><strong>データソース:</strong> ${log.データソース || '-'}</div>
            <div><strong>店舗ID:</strong> ${log.店舗ID || '-'}</div>
            <div><strong>収集開始日時:</strong> ${log.収集開始日時 ? new Date(log.収集開始日時).toLocaleString() : '-'}</div>
            <div><strong>収集終了日時:</strong> ${log.収集終了日時 ? new Date(log.収集終了日時).toLocaleString() : '-'}</div>
            <div><strong>処理ステータス:</strong> ${log.処理ステータス || '-'}</div>
            <div><strong>対象期間:</strong> ${log.対象期間開始日 || '-'} ～ ${log.対象期間終了日 || '-'}</div>
            <div><strong>収集件数:</strong> ${log.収集件数 || 0}</div>
            <div><strong>エラー件数:</strong> ${log.エラー件数 || 0}</div>
            <div><strong>処理時間:</strong> ${log.処理時間秒 || 0}秒</div>
            <div><strong>データ品質スコア:</strong> ${log.データ品質スコア || '-'}</div>
            <div><strong>エラーメッセージ:</strong><br><pre style="background: var(--bg-main); padding: 10px; border-radius: 4px; white-space: pre-wrap; max-height: 200px; overflow-y: auto;">${log.エラーメッセージ || 'なし'}</pre></div>
            <div><strong>備考:</strong> ${log.備考 || '-'}</div>
          </div>
        `;
        logDetailModal.classList.remove('hidden');
      }
    }

    // 再実行
    const retryBtn = e.target.closest('.retry-btn');
    if (retryBtn) {
      if (!confirm('エラーログを再実行しますか？')) return;

      const logId = retryBtn.dataset.id;
      try {
        // 実際の実装では再実行APIを呼び出し
        // ここではステータス更新のシミュレーション
        await window.aivicApi.update(11, logId, { 
          処理ステータス: '実行中',
          更新日時: new Date().toISOString()
        });

        // 少し待ってから成功状態に更新
        setTimeout(async () => {
          await window.aivicApi.update(11, logId, { 
            処理ステータス: '成功',
            エラー件数: 0,
            エラーメッセージ: null,
            更新日時: new Date().toISOString()
          });

          const logs = await window.aivicApi.list(11);
          if (logs) renderLogs(logs);
        }, 2000);

        const logs = await window.aivicApi.list(11);
        if (logs) renderLogs(logs);
      } catch (error) {
        alert('エラーログの再実行が失敗しました');
      }
    }

    // モーダルクローズ
    if (e.target.closest('#btn-close-modal')) {
      logDetailModal.classList.add('hidden');
    }
  });

  // モーダル外クリックで閉じる
  logDetailModal.addEventListener('click', (e) => {
    if (e.target === logDetailModal) {
      logDetailModal.classList.add('hidden');
    }
  });

  alertSettingsModal.addEventListener('click', (e) => {
    if (e.target === alertSettingsModal) {
      alertSettingsModal.classList.add('hidden');
    }
  });

  // クリーンアップ
  return () => {
    if (autoUpdateInterval) {
      clearInterval(autoUpdateInterval);
    }
  };
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#history-tbody");
  const modal = container.querySelector("#detail-modal");

  let currentPage = 1;
  const itemsPerPage = 20;
  let allRows = [];
  let filteredRows = [];
  let users = [];

  // ユーザー一覧を取得してセレクトボックスに設定
  async function loadUsers() {
    try {
      const userRows = await window.aivicApi.list(0); // ログインユーザーテーブル
      if (userRows) {
        users = userRows;
        const userSelect = container.querySelector("#user-filter");
        userSelect.innerHTML = '<option value="">全ユーザー</option>';
        users.forEach(user => {
          userSelect.innerHTML += `<option value="${user.ユーザーID}">${user.ユーザー名}</option>`;
        });
      }
    } catch (error) {
      console.error('ユーザー一覧の取得に失敗しました:', error);
    }
  }

  // 操作履歴テーブル再描画関数
  function renderRows(rows) {
    const startIndex = (currentPage - 1) * itemsPerPage;
    const endIndex = startIndex + itemsPerPage;
    const pageRows = rows.slice(startIndex, endIndex);

    tbody.innerHTML = pageRows.map(r => {
      const user = users.find(u => u.ユーザーID === r.ユーザーID);
      const userName = user ? user.ユーザー名 : 'Unknown';
      const operationDate = r.操作日時 ? new Date(r.操作日時).toLocaleString('ja-JP') : '';
      const resultClass = r.処理結果 === '成功' ? 'status-success' : r.処理結果 === '失敗' || r.処理結果 === 'エラー' ? 'status-error' : '';

      return `<tr data-id="${r.操作履歴ID || ''}">
        <td>${operationDate}</td>
        <td>${userName}</td>
        <td>${r.操作種別 || ''}</td>
        <td>${r.操作画面 || ''}</td>
        <td>${r.IPアドレス || ''}</td>
        <td><span class="${resultClass}">${r.処理結果 || ''}</span></td>
        <td>
          <button class="action-btn secondary detail-btn" data-id="${r.操作履歴ID || ''}">詳細</button>
        </td>
      </tr>`;
    }).join("");

    updatePaginationInfo(rows.length, startIndex, endIndex);
    renderPagination(rows.length);
  }

  // ページネーション情報更新
  function updatePaginationInfo(totalItems, startIndex, endIndex) {
    const info = container.querySelector("#pagination-info");
    const actualEnd = Math.min(endIndex, totalItems);
    info.textContent = `${totalItems}件中 ${startIndex + 1}-${actualEnd}件を表示`;
  }

  // ページネーション描画
  function renderPagination(totalItems) {
    const totalPages = Math.ceil(totalItems / itemsPerPage);
    const pageNumbers = container.querySelector("#page-numbers");
    const prevBtn = container.querySelector("#btn-prev");
    const nextBtn = container.querySelector("#btn-next");

    prevBtn.disabled = currentPage === 1;
    nextBtn.disabled = currentPage === totalPages || totalPages === 0;

    pageNumbers.innerHTML = '';

    if (totalPages <= 1) return;

    const startPage = Math.max(1, currentPage - 2);
    const endPage = Math.min(totalPages, currentPage + 2);

    for (let i = startPage; i <= endPage; i++) {
      const btn = document.createElement('button');
      btn.className = `page-btn ${i === currentPage ? 'active' : ''}`;
      btn.textContent = i;
      btn.addEventListener('click', () => {
        currentPage = i;
        renderRows(filteredRows);
      });
      pageNumbers.appendChild(btn);
    }
  }

  // フィルタリング関数
  function applyFilters() {
    const startDate = container.querySelector("#start-date").value;
    const endDate = container.querySelector("#end-date").value;
    const userFilter = container.querySelector("#user-filter").value;
    const operationFilter = container.querySelector("#operation-type-filter").value;
    const screenSearch = container.querySelector("#screen-search").value.toLowerCase();
    const ipSearch = container.querySelector("#ip-search").value.toLowerCase();
    const resultFilter = container.querySelector("#result-filter").value;

    // 日付範囲バリデーション
    if (startDate && endDate && new Date(startDate) > new Date(endDate)) {
      alert('開始日が終了日より後の日付になっています。正しい日付範囲を入力してください。');
      return;
    }

    filteredRows = allRows.filter(row => {
      // 日付範囲フィルター
      if (startDate || endDate) {
        const rowDate = row.操作日時 ? new Date(row.操作日時).toISOString().split('T')[0] : '';
        if (startDate && rowDate < startDate) return false;
        if (endDate && rowDate > endDate) return false;
      }

      // ユーザーフィルター
      if (userFilter && row.ユーザーID !== userFilter) return false;

      // 操作種別フィルター
      if (operationFilter && row.操作種別 !== operationFilter) return false;

      // 画面名検索
      if (screenSearch && !row.操作画面?.toLowerCase().includes(screenSearch)) return false;

      // IPアドレス検索
      if (ipSearch) {
        // IPアドレス形式バリデーション
        const ipPattern = /^(\d{1,3}\.){3}\d{1,3}$/;
        if (ipSearch && !ipPattern.test(ipSearch) && ipSearch.length > 0) {
          alert('不正なIPアドレス形式です。正しい形式（例：192.168.1.100）で入力してください。');
          return false;
        }
        if (!row.IPアドレス?.toLowerCase().includes(ipSearch)) return false;
      }

      // 処理結果フィルター
      if (resultFilter && row.処理結果 !== resultFilter) return false;

      return true;
    });

    currentPage = 1;
    renderRows(filteredRows);
  }

  // 詳細モーダル表示
  function showDetailModal(historyId) {
    const history = allRows.find(r => r.操作履歴ID === historyId);
    if (!history) return;

    const user = users.find(u => u.ユーザーID === history.ユーザーID);
    const userName = user ? user.ユーザー名 : 'Unknown';

    container.querySelector("#detail-id").textContent = history.操作履歴ID || '';
    container.querySelector("#detail-datetime").textContent = history.操作日時 ? new Date(history.操作日時).toLocaleString('ja-JP') : '';
    container.querySelector("#detail-user").textContent = userName;
    container.querySelector("#detail-operation").textContent = history.操作種別 || '';
    container.querySelector("#detail-screen").textContent = history.操作画面 || '';
    container.querySelector("#detail-table").textContent = history.操作対象テーブル || '';
    container.querySelector("#detail-target-id").textContent = history.操作対象ID || '';
    container.querySelector("#detail-ip").textContent = history.IPアドレス || '';
    container.querySelector("#detail-user-agent").textContent = history.ユーザーエージェント || '';
    container.querySelector("#detail-result").textContent = history.処理結果 || '';
    container.querySelector("#detail-processing-time").textContent = history.処理時間 ? `${history.処理時間}ms` : '';
    container.querySelector("#detail-content").textContent = history.操作内容 || '';
    container.querySelector("#detail-error").textContent = history.エラーメッセージ || '';

    modal.classList.remove('hidden');
  }

  // CSV出力
  function exportCSV() {
    if (filteredRows.length === 0) {
      alert('出力するデータがありません。');
      return;
    }

    // 大量データの場合の警告
    if (filteredRows.length > 100000) {
      alert('データ量が多すぎるため、CSV出力でタイムアウトエラーが発生する可能性があります。検索条件を絞り込んでから再度お試しください。');
      return;
    }

    const headers = ['操作日時', 'ユーザー名', '操作種別', '操作画面', 'IPアドレス', '処理結果', '操作内容', 'エラーメッセージ'];
    const csvContent = [
      headers.join(','),
      ...filteredRows.map(row => {
        const user = users.find(u => u.ユーザーID === row.ユーザーID);
        const userName = user ? user.ユーザー名 : 'Unknown';
        const operationDate = row.操作日時 ? new Date(row.操作日時).toLocaleString('ja-JP') : '';

        return [
          `"${operationDate}"`,
          `"${userName}"`,
          `"${row.操作種別 || ''}"`,
          `"${row.操作画面 || ''}"`,
          `"${row.IPアドレス || ''}"`,
          `"${row.処理結果 || ''}"`,
          `"${(row.操作内容 || '').replace(/"/g, '""')}"`,
          `"${(row.エラーメッセージ || '').replace(/"/g, '""')}"`
        ].join(',');
      })
    ].join('\n');

    const bom = '\uFEFF';
    const blob = new Blob([bom + csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `操作履歴_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 初期データ読み込み
  async function loadData() {
    try {
      await loadUsers();
      const rows = await window.aivicApi.list(12); // システム操作履歴テーブル
      if (rows) {
        allRows = rows.sort((a, b) => new Date(b.操作日時) - new Date(a.操作日時));
        filteredRows = [...allRows];
        renderRows(filteredRows);
      } else {
        allRows = tables[12]?.records || [];
        filteredRows = [...allRows];
        renderRows(filteredRows);
      }
    } catch (error) {
      console.error('データの読み込みに失敗しました:', error);
      allRows = tables[12]?.records || [];
      filteredRows = [...allRows];
      renderRows(filteredRows);
    }
  }

  // イベントリスナー登録
  container.querySelector("#btn-search").addEventListener("click", applyFilters);

  container.querySelector("#btn-clear").addEventListener("click", () => {
    container.querySelector("#start-date").value = '';
    container.querySelector("#end-date").value = '';
    container.querySelector("#user-filter").value = '';
    container.querySelector("#operation-type-filter").value = '';
    container.querySelector("#screen-search").value = '';
    container.querySelector("#ip-search").value = '';
    container.querySelector("#result-filter").value = '';

    filteredRows = [...allRows];
    currentPage = 1;
    renderRows(filteredRows);
  });

  container.querySelector("#btn-csv-export").addEventListener("click", exportCSV);

  container.querySelector("#btn-prev").addEventListener("click", () => {
    if (currentPage > 1) {
      currentPage--;
      renderRows(filteredRows);
    }
  });

  container.querySelector("#btn-next").addEventListener("click", () => {
    const totalPages = Math.ceil(filteredRows.length / itemsPerPage);
    if (currentPage < totalPages) {
      currentPage++;
      renderRows(filteredRows);
    }
  });

  container.querySelector("#btn-close-modal").addEventListener("click", () => {
    modal.classList.add('hidden');
  });

  modal.addEventListener("click", (e) => {
    if (e.target === modal) {
      modal.classList.add('hidden');
    }
  });

  // イベントデリゲーション
  container.addEventListener("click", (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      showDetailModal(detailBtn.dataset.id);
    }
  });

  // 初期データ読み込み
  loadData();
}

function(container, apiUrl, tables) {
  let isProcessing = false;
  let processingInterval = null;

  // 初期データの設定
  function initializeData() {
    // 店舗データの設定
    const storeSelect = container.querySelector('#store-select');
    const storeTable = tables.find(t => t.tableName === '店舗マスタ');
    if (storeTable && storeTable.records) {
      storeTable.records.forEach(store => {
        if (store.有効フラグ) {
          const option = document.createElement('option');
          option.value = store.店舗ID;
          option.textContent = `${store.店舗名} (${store.店舗コード})`;
          storeSelect.appendChild(option);
        }
      });
    }

    // 商品カテゴリの設定（サンプルデータ）
    const categoryContainer = container.querySelector('#category-checkboxes');
    const categories = ['食品', '日用品', '衣料品', '家電', '書籍・文具', '医薬品'];
    categories.forEach((category, index) => {
      const label = document.createElement('label');
      label.style.display = 'block';
      label.style.marginBottom = '8px';
      label.style.color = 'var(--text)';
      label.style.cursor = 'pointer';
      label.innerHTML = `<input type="checkbox" class="category-checkbox" value="${category}" style="margin-right: 8px;"> ${category}`;
      categoryContainer.appendChild(label);
    });

    // 季節要因スライダーの値表示更新
    const seasonalSlider = container.querySelector('#seasonal-factor');
    const seasonalValue = container.querySelector('#seasonal-value');
    seasonalSlider.addEventListener('input', () => {
      seasonalValue.textContent = seasonalSlider.value;
    });

    // 全選択チェックボックスの処理
    const selectAllCheckbox = container.querySelector('#select-all-categories');
    const categoryCheckboxes = container.querySelectorAll('.category-checkbox');

    selectAllCheckbox.addEventListener('change', () => {
      categoryCheckboxes.forEach(cb => {
        cb.checked = selectAllCheckbox.checked;
      });
    });

    categoryCheckboxes.forEach(cb => {
      cb.addEventListener('change', () => {
        const allChecked = Array.from(categoryCheckboxes).every(checkbox => checkbox.checked);
        const noneChecked = Array.from(categoryCheckboxes).every(checkbox => !checkbox.checked);
        selectAllCheckbox.checked = allChecked;
        selectAllCheckbox.indeterminate = !allChecked && !noneChecked;
      });
    });

    // デフォルト日付設定
    const today = new Date();
    const nextWeek = new Date(today);
    nextWeek.setDate(today.getDate() + 7);
    const lastMonth = new Date(today);
    lastMonth.setMonth(today.getMonth() - 1);

    container.querySelector('#prediction-start-date').value = today.toISOString().split('T')[0];
    container.querySelector('#prediction-end-date').value = nextWeek.toISOString().split('T')[0];
    container.querySelector('#learning-start-date').value = lastMonth.toISOString().split('T')[0];
    container.querySelector('#learning-end-date').value = today.toISOString().split('T')[0];
  }

  // バリデーション関数
  function validateForm() {
    const errors = [];

    const predictionStartDate = container.querySelector('#prediction-start-date').value;
    const predictionEndDate = container.querySelector('#prediction-end-date').value;
    const storeId = container.querySelector('#store-select').value;
    const selectedCategories = Array.from(container.querySelectorAll('.category-checkbox:checked'));
    const selectedModel = container.querySelector('input[name="prediction-model"]:checked');
    const learningStartDate = container.querySelector('#learning-start-date').value;
    const learningEndDate = container.querySelector('#learning-end-date').value;

    if (!predictionStartDate || !predictionEndDate) {
      errors.push('予測期間の開始日と終了日を入力してください');
    }

    if (!storeId) {
      errors.push('店舗を選択してください');
    }

    if (selectedCategories.length === 0) {
      errors.push('商品カテゴリを選択してください');
    }

    if (!selectedModel) {
      errors.push('予測モデルを選択してください');
    }

    if (!learningStartDate || !learningEndDate) {
      errors.push('学習データ期間の開始日と終了日を入力してください');
    }

    // 日付の妥当性チェック
    if (predictionStartDate && predictionEndDate) {
      const startDate = new Date(predictionStartDate);
      const endDate = new Date(predictionEndDate);
      const today = new Date();
      today.setHours(0, 0, 0, 0);

      if (startDate < today) {
        errors.push('予測期間に過去の日付は指定できません');
      }

      if (endDate <= startDate) {
        errors.push('予測期間の終了日は開始日より後の日付を指定してください');
      }

      // 1年超チェック
      const oneYearLater = new Date(startDate);
      oneYearLater.setFullYear(startDate.getFullYear() + 1);
      if (endDate > oneYearLater) {
        errors.push('予測期間は1年以内で設定してください');
      }
    }

    // 学習データ期間チェック
    if (learningStartDate && learningEndDate && predictionStartDate && predictionEndDate) {
      const learningStart = new Date(learningStartDate);
      const learningEnd = new Date(learningEndDate);
      const predictionStart = new Date(predictionStartDate);
      const predictionEnd = new Date(predictionEndDate);

      const learningDays = Math.ceil((learningEnd - learningStart) / (1000 * 60 * 60 * 24));
      const predictionDays = Math.ceil((predictionEnd - predictionStart) / (1000 * 60 * 60 * 24));

      if (learningDays < predictionDays) {
        errors.push('学習データ期間は予測期間以上に設定してください');
      }
    }

    return errors;
  }

  // エラー表示関数
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    const successDiv = container.querySelector('#success-message');

    successDiv.classList.add('hidden');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');

    setTimeout(() => {
      errorDiv.classList.add('hidden');
    }, 5000);
  }

  // 成功表示関数
  function showSuccess(message) {
    const errorDiv = container.querySelector('#error-message');
    const successDiv = container.querySelector('#success-message');

    errorDiv.classList.add('hidden');
    successDiv.textContent = message;
    successDiv.classList.remove('hidden');

    setTimeout(() => {
      successDiv.classList.add('hidden');
    }, 3000);
  }

  // 進捗バー表示/更新
  function updateProgress(percentage, text) {
    const progressContainer = container.querySelector('#progress-container');
    const progressBar = container.querySelector('#progress-bar');
    const progressText = container.querySelector('#progress-text');
    const progressPercentage = container.querySelector('#progress-percentage');

    progressContainer.classList.remove('hidden');
    progressBar.style.width = percentage + '%';
    progressText.textContent = text || '処理中...';
    progressPercentage.textContent = percentage + '%';
  }

  // 進捗バー非表示
  function hideProgress() {
    const progressContainer = container.querySelector('#progress-container');
    progressContainer.classList.add('hidden');
  }

  // UI無効化/有効化
  function setUIEnabled(enabled) {
    const executeBtn = container.querySelector('#btn-execute-prediction');
    const cancelBtn = container.querySelector('#btn-cancel-prediction');
    const inputs = container.querySelectorAll('input, select, button:not(#btn-cancel-prediction)');

    if (enabled) {
      executeBtn.classList.remove('hidden');
      cancelBtn.classList.add('hidden');
      inputs.forEach(input => input.disabled = false);
    } else {
      executeBtn.classList.add('hidden');
      cancelBtn.classList.remove('hidden');
      inputs.forEach(input => {
        if (input.id !== 'btn-cancel-prediction') {
          input.disabled = true;
        }
      });
    }
  }

  // 予測結果表示
  function displayResults(results) {
    const resultsDiv = container.querySelector('#prediction-results');
    const tbody = container.querySelector('#results-tbody');

    tbody.innerHTML = results.map(result => `
      <tr data-id="${result.予測結果ID}">
        <td>${result.店舗名 || ''}</td>
        <td>${result.商品名 || ''}</td>
        <td>${result.予測対象日 ? new Date(result.予測対象日).toLocaleDateString() : ''}</td>
        <td>${result.予測数量 || 0}</td>
        <td>${result.予測精度 || 0}%</td>
        <td>${result.推奨発注数量 || 0}</td>
        <td>
          <button class="action-btn secondary view-detail-btn" data-id="${result.予測結果ID}">詳細</button>
        </td>
      </tr>
    `).join('');

    resultsDiv.classList.remove('hidden');
  }

  // 天候データ取込処理
  async function importWeatherData() {
    try {
      updateProgress(0, '天候データを取得中...');

      // 模擬的な処理
      for (let i = 0; i <= 100; i += 20) {
        await new Promise(resolve => setTimeout(resolve, 200));
        updateProgress(i, '天候データを取得中...');
      }

      hideProgress();
      showSuccess('天候データの取込が完了しました');
    } catch (error) {
      hideProgress();
      showError('天候データの取得に失敗しました。データソースの設定を確認してください。');
    }
  }

  // イベントデータ取込処理
  async function importEventData() {
    try {
      updateProgress(0, 'イベントデータを取得中...');

      // 模擬的な処理
      for (let i = 0; i <= 100; i += 25) {
        await new Promise(resolve => setTimeout(resolve, 150));
        updateProgress(i, 'イベントデータを取得中...');
      }

      hideProgress();
      showSuccess('イベントデータの取込が完了しました');
    } catch (error) {
      hideProgress();
      showError('イベントデータの取込に失敗しました。ファイル形式を確認してください。');
    }
  }

  // AI予測実行処理
  async function executePrediction() {
    const errors = validateForm();
    if (errors.length > 0) {
      showError(errors.join('\n'));
      return;
    }

    isProcessing = true;
    setUIEnabled(false);

    try {
      // 予測処理の模擬実行
      const steps = [
        { progress: 10, text: 'データを準備中...' },
        { progress: 30, text: '学習データを読み込み中...' },
        { progress: 50, text: 'AIモデルを学習中...' },
        { progress: 70, text: '需要予測を計算中...' },
        { progress: 90, text: '結果を生成中...' },
        { progress: 100, text: '処理完了' }
      ];

      for (const step of steps) {
        if (!isProcessing) break; // 中止された場合

        await new Promise(resolve => setTimeout(resolve, 800));
        updateProgress(step.progress, step.text);
      }

      if (isProcessing) {
        // 模擬的な予測結果データ
        const mockResults = [
          {
            予測結果ID: 'pred-001',
            店舗名: 'サンプル店舗A',
            商品名: '商品A',
            予測対象日: new Date(Date.now() + 86400000).toISOString(),
            予測数量: 150,
            予測精度: 85,
            推奨発注数量: 160
          },
          {
            予測結果ID: 'pred-002',
            店舗名: 'サンプル店舗A',
            商品名: '商品B',
            予測対象日: new Date(Date.now() + 86400000).toISOString(),
            予測数量: 200,
            予測精度: 78,
            推奨発注数量: 210
          }
        ];

        hideProgress();
        displayResults(mockResults);
        showSuccess('AI需要予測処理が正常に完了しました');
      }
    } catch (error) {
      hideProgress();
      showError('AI予測実行が失敗しました。システム管理者にお問い合わせください。');
    } finally {
      isProcessing = false;
      setUIEnabled(true);
    }
  }

  // 処理中止
  function cancelPrediction() {
    if (confirm('予測処理を中止しますか？')) {
      isProcessing = false;
      hideProgress();
      setUIEnabled(true);
      showError('予測処理が中止されました');
    }
  }

  // CSVエクスポート
  function exportResults() {
    const tbody = container.querySelector('#results-tbody');
    const rows = Array.from(tbody.querySelectorAll('tr'));

    if (rows.length === 0) {
      showError('エクスポートする結果がありません');
      return;
    }

    const headers = ['店舗名', '商品名', '予測日', '予測数量', '予測精度', '推奨発注数量'];
    const csvData = [headers];

    rows.forEach(row => {
      const cells = Array.from(row.querySelectorAll('td')).slice(0, 6);
      csvData.push(cells.map(cell => cell.textContent.trim()));
    });

    const csvContent = '\uFEFF' + csvData.map(row => 
      row.map(field => `"${field.replace(/"/g, '""')}"`).join(',')
    ).join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `需要予測結果_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // イベントリスナーの設定
  container.querySelector('#btn-weather-import').addEventListener('click', importWeatherData);
  container.querySelector('#btn-event-import').addEventListener('click', importEventData);
  container.querySelector('#btn-execute-prediction').addEventListener('click', executePrediction);
  container.querySelector('#btn-cancel-prediction').addEventListener('click', cancelPrediction);
  container.querySelector('#btn-export-results').addEventListener('click', exportResults);

  // 初期化実行
  initializeData();
}

function(container, apiUrl, tables) {
  let selectedProduct = null;
  let predictionData = null;

  // エラー表示関数
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    const errorText = container.querySelector('#error-text');
    errorText.textContent = message;
    errorDiv.style.display = 'block';
    setTimeout(() => {
      errorDiv.style.display = 'none';
    }, 5000);
  }

  // 店舗データ読み込み
  function loadStores() {
    window.aivicApi.list(1).then(stores => {
      const storeSelect = container.querySelector('#store-select');
      storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';
      if (stores) {
        stores.filter(s => s.有効フラグ).forEach(store => {
          const option = document.createElement('option');
          option.value = store.店舗ID;
          option.textContent = `${store.店舗コード} - ${store.店舗名}`;
          storeSelect.appendChild(option);
        });
      }
    });
  }

  // 商品データ読み込み・表示
  function renderProducts(products) {
    const tbody = container.querySelector('#product-tbody');
    if (!products || products.length === 0) {
      tbody.innerHTML = '<tr><td colspan="7" style="text-align: center; color: var(--text-muted);">商品が見つかりません</td></tr>';
      return;
    }

    tbody.innerHTML = products.map(product => `
      <tr data-id="${product.商品ID}" style="cursor: pointer;">
        <td><input type="radio" name="product-select" value="${product.商品ID}" data-product='${JSON.stringify(product)}'></td>
        <td style="color: var(--text);">${product.商品コード || ''}</td>
        <td style="color: var(--text);">${product.商品名 || ''}</td>
        <td style="color: var(--text-muted);">${product.商品カテゴリID || ''}</td>
        <td style="color: var(--text);">${product.単価 ? product.単価.toLocaleString() + '円' : ''}</td>
        <td style="color: var(--text);">${product.発注単位 || ''}</td>
        <td style="color: var(--text);">${product.リードタイム日数 || ''}日</td>
      </tr>
    `).join('');
  }

  // 商品検索・絞り込み
  function searchProducts() {
    const storeId = container.querySelector('#store-select').value;
    const categoryId = container.querySelector('#category-select').value;
    const searchKeyword = container.querySelector('#product-search').value.toLowerCase();

    if (!storeId) {
      showError('店舗を選択してください');
      return;
    }

    window.aivicApi.list(2).then(products => {
      if (!products) return;

      let filtered = products.filter(p => p.有効フラグ && p.AI予測対象フラグ);

      if (categoryId) {
        filtered = filtered.filter(p => p.商品カテゴリID === categoryId);
      }

      if (searchKeyword) {
        filtered = filtered.filter(p => 
          (p.商品名 && p.商品名.toLowerCase().includes(searchKeyword)) ||
          (p.商品コード && p.商品コード.toLowerCase().includes(searchKeyword))
        );
      }

      renderProducts(filtered);
    });
  }

  // AI予測実行
  function executePrediction() {
    const storeId = container.querySelector('#store-select').value;
    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;

    if (!storeId) {
      showError('店舗を選択してください');
      return;
    }
    if (!startDate || !endDate) {
      showError('対象期間を設定してください');
      return;
    }
    if (!selectedProduct) {
      showError('商品を選択してください');
      return;
    }

    // 需要予測結果を取得
    window.aivicApi.list(8).then(predictions => {
      if (!predictions) return;

      const prediction = predictions.find(p => 
        p.店舗ID === storeId && 
        p.商品ID === selectedProduct.商品ID &&
        p.予測対象日>= startDate && 
        p.予測対象日<= endDate
      );

      const resultDiv = container.querySelector('#prediction-result');
      if (prediction) {
        predictionData = prediction;
        resultDiv.innerHTML = `
          <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 12px;">
            <div>
              <p style="color: var(--text-muted); margin: 0; font-size: 12px;">予測数量</p>
              <p style="color: var(--text); margin: 0; font-weight: 600; font-size: 16px;">${prediction.予測数量}個</p>
            </div>
            <div>
              <p style="color: var(--text-muted); margin: 0; font-size: 12px;">予測精度</p>
              <p style="color: var(--text); margin: 0; font-weight: 600; font-size: 16px;">${prediction.予測精度 || 85}%</p>
            </div>
            <div>
              <p style="color: var(--text-muted); margin: 0; font-size: 12px;">推奨発注数量</p>
              <p style="color: var(--text); margin: 0; font-weight: 600; font-size: 16px;">${prediction.推奨発注数量}個</p>
            </div>
          </div>
        `;
      } else {
        resultDiv.innerHTML = '<p style="color: var(--text-muted); margin: 0;">該当期間の予測データが見つかりません</p>';
      }
    });
  }

  // 発注量計算
  function calculateOrderQuantity() {
    const currentStock = parseInt(container.querySelector('#current-stock').value) || 0;
    const safetyStock = parseInt(container.querySelector('#safety-stock').value) || 0;
    const leadTime = parseInt(container.querySelector('#lead-time').value) || 0;
    const weatherImpact = parseInt(container.querySelector('#weather-impact').value) || 100;
    const eventImpact = parseInt(container.querySelector('#event-impact').value) || 100;
    const seasonalFactor = parseFloat(container.querySelector('#seasonal-factor').value) || 1.0;

    // バリデーション
    if (currentStock < 0) {
      showError('在庫数は0以上の値を入力してください');
      return;
    }
    if (isNaN(safetyStock) || safetyStock < 0) {
      showError('安全在庫は0以上の数値を入力してください');
      return;
    }
    if (leadTime < 1 || leadTime > 365) {
      showError('リードタイムは1-365日の範囲で入力してください');
      return;
    }
    if (weatherImpact < 0 || weatherImpact > 200) {
      showError('天候影響度は0-200%の範囲で入力してください');
      return;
    }
    if (eventImpact < 0 || eventImpact > 200) {
      showError('イベント影響度は0-200%の範囲で入力してください');
      return;
    }
    if (seasonalFactor < 0.1 || seasonalFactor > 10) {
      showError('季節補正係数は0.1-10の範囲で入力してください');
      return;
    }

    if (!predictionData) {
      showError('AI予測を実行してください');
      return;
    }

    // 発注量計算ロジック
    let baseDemand = predictionData.予測数量 || 0;

    // 影響度調整を適用
    baseDemand = baseDemand * (weatherImpact / 100) * (eventImpact / 100) * seasonalFactor;

    // リードタイム期間の需要を考慮
    const leadTimeDemand = baseDemand * (leadTime / 7); // 週単位で計算

    // 発注量 = リードタイム期間需要 + 安全在庫 - 現在在庫
    const recommendedQty = Math.max(0, Math.ceil(leadTimeDemand + safetyStock - currentStock));

    // 発注単位で調整
    const orderUnit = selectedProduct.発注単位 || 1;
    const adjustedQty = Math.ceil(recommendedQty / orderUnit) * orderUnit;

    // 結果表示
    container.querySelector('#ai-recommended').value = adjustedQty;
    container.querySelector('#final-order-qty').value = adjustedQty;
    container.querySelector('#result-area').style.display = 'block';
  }

  // 初期データ読み込み
  loadStores();
  renderProducts(tables[2]?.records || []);

  // イベントリスナー設定
  container.querySelector('#btn-search').addEventListener('click', searchProducts);

  container.querySelector('#btn-ai-predict').addEventListener('click', executePrediction);

  container.querySelector('#btn-calculate').addEventListener('click', calculateOrderQuantity);

  // 商品選択
  container.addEventListener('change', (e) => {
    if (e.target.name === 'product-select') {
      selectedProduct = JSON.parse(e.target.dataset.product);
      container.querySelector('#selected-product-name').textContent = selectedProduct.商品名;
      container.querySelector('#calculation-area').style.display = 'block';
      container.querySelector('#lead-time').value = selectedProduct.リードタイム日数 || 7;
    }
  });

  // スライダー値更新
  container.querySelector('#weather-impact').addEventListener('input', (e) => {
    container.querySelector('#weather-value').textContent = e.target.value + '%';
  });

  container.querySelector('#event-impact').addEventListener('input', (e) => {
    container.querySelector('#event-value').textContent = e.target.value + '%';
  });

  // 手動調整
  container.querySelector('#manual-adjustment').addEventListener('input', (e) => {
    const manualQty = parseInt(e.target.value);
    if (manualQty < 0) {
      showError('発注量は0以上の値を入力してください');
      e.target.value = '';
      return;
    }

    const finalQty = manualQty || parseInt(container.querySelector('#ai-recommended').value) || 0;
    container.querySelector('#final-order-qty').value = finalQty;
  });

  // 発注書作成
  container.querySelector('#btn-create-order').addEventListener('click', () => {
    window.showScreen('scr-1778591907544');
  });

  // 計算結果保存
  container.querySelector('#btn-save-calculation').addEventListener('click', async () => {
    const finalQty = parseInt(container.querySelector('#final-order-qty').value);
    if (!finalQty || !selectedProduct) return;

    const orderData = {
      店舗ID: container.querySelector('#store-select').value,
      商品ID: selectedProduct.商品ID,
      需要予測結果ID: predictionData?.予測結果ID,
      発注日: new Date().toISOString(),
      納期予定日: new Date(Date.now() + (selectedProduct.リードタイム日数 || 7) * 24 * 60 * 60 * 1000).toISOString(),
      発注数量: finalQty,
      予測数量: predictionData?.予測数量,
      発注単価: selectedProduct.単価,
      発注金額: finalQty * selectedProduct.単価,
      発注方法: container.querySelector('#manual-adjustment').value ? 'AI推奨修正' : 'AI推奨採用',
      発注ステータス: '発注済',
      仕入先ID: selectedProduct.仕入先ID,
      自動発注フラグ: false,
      作成者ID: 'current-user',
      更新者ID: 'current-user'
    };

    const saved = await window.aivicApi.save(9, orderData);
    if (saved) {
      alert('計算結果を保存しました');
    }
  });

  // リセット
  container.querySelector('#btn-reset').addEventListener('click', () => {
    container.querySelector('#calculation-area').style.display = 'none';
    container.querySelector('#result-area').style.display = 'none';
    selectedProduct = null;
    predictionData = null;

    // フォームリセット
    container.querySelectorAll('input[type="number"], input[type="date"], input[type="text"]').forEach(input => {
      input.value = '';
    });
    container.querySelector('#weather-impact').value = 100;
    container.querySelector('#event-impact').value = 100;
    container.querySelector('#seasonal-factor').value = 1.0;
    container.querySelector('#weather-value').textContent = '100%';
    container.querySelector('#event-value').textContent = '100%';

    // 商品選択解除
    container.querySelectorAll('input[name="product-select"]').forEach(radio => {
      radio.checked = false;
    });
  });
}

function(container, apiUrl, tables) {
  let storeData = [];
  let productData = [];
  let demandForecastData = [];
  let salesData = [];
  let orderData = [];
  let orderItems = [];
  let selectedCategory = '';

  // テーブルデータの初期化
  function initializeData() {
    storeData = tables.find(t => t.tableName === '店舗マスタ')?.records || [];
    productData = tables.find(t => t.tableName === '商品マスタ')?.records || [];
    demandForecastData = tables.find(t => t.tableName === '需要予測結果')?.records || [];
    salesData = tables.find(t => t.tableName === '売上実績データ')?.records || [];
    orderData = tables.find(t => t.tableName === '発注データ')?.records || [];
  }

  // 店舗選択肢の描画
  function renderStoreOptions() {
    const storeSelect = container.querySelector('#store-select');
    storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';
    storeData.forEach(store => {
      if (store.有効フラグ) {
        storeSelect.innerHTML += `<option value="${store.店舗ID}">${store.店舗名}</option>`;
      }
    });
  }

  // 商品一覧の描画
  function renderProductList(products = productData) {
    const tbody = container.querySelector('#product-list-tbody');
    const filteredProducts = products.filter(product => {
      if (!product.有効フラグ) return false;
      if (selectedCategory && product.商品カテゴリID !== selectedCategory) return false;
      return true;
    });

    tbody.innerHTML = filteredProducts.map(product => {
      const forecast = demandForecastData.find(f => f.商品ID === product.商品ID);
      const predictedQty = forecast ? forecast.予測数量 : 0;

      return `
        <tr data-product-id="${product.商品ID}">
          <td><input type="checkbox" class="product-checkbox" data-product-id="${product.商品ID}"></td>
          <td>${product.商品コード || ''}</td>
          <td>${product.商品名 || ''}</td>
          <td>${product.商品カテゴリID || ''}</td>
          <td>¥${(product.単価 || 0).toLocaleString()}</td>
          <td>-</td>
          <td>${predictedQty}</td>
          <td><input type="number" class="quantity-input" min="0" value="${predictedQty}" data-product-id="${product.商品ID}"></td>
          <td>
            <button class="prediction-btn" data-product-id="${product.商品ID}">予測根拠</button>
            <button class="action-btn secondary add-to-order-btn" data-product-id="${product.商品ID}">追加</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 発注商品一覧の描画
  function renderOrderItems() {
    const tbody = container.querySelector('#order-items-tbody');
    tbody.innerHTML = orderItems.map(item => {
      const amount = item.quantity * item.price;
      return `
        <tr data-order-item-id="${item.productId}">
          <td>${item.productCode}</td>
          <td>${item.productName}</td>
          <td>${item.predictedQty}</td>
          <td><input type="number" class="quantity-input" min="1" value="${item.quantity}" data-product-id="${item.productId}"></td>
          <td>¥${item.price.toLocaleString()}</td>
          <td>¥${amount.toLocaleString()}</td>
          <td><button class="remove-btn" data-product-id="${item.productId}">削除</button></td>
        </tr>
      `;
    }).join('');

    updateTotalAmount();
  }

  // 発注総額の更新
  function updateTotalAmount() {
    const total = orderItems.reduce((sum, item) => sum + (item.quantity * item.price), 0);
    container.querySelector('#total-amount').textContent = `¥${total.toLocaleString()}`;
  }

  // バリデーション
  function validateForm() {
    const errors = [];

    const storeId = container.querySelector('#store-select').value;
    if (!storeId) {
      errors.push('店舗を選択してください');
    }

    const orderDate = container.querySelector('#order-date').value;
    if (!orderDate) {
      errors.push('発注日付を入力してください');
    }

    const deliveryDate = container.querySelector('#delivery-date').value;
    if (!deliveryDate) {
      errors.push('納期を指定してください');
    }

    if (orderDate && deliveryDate && new Date(deliveryDate) <= new Date(orderDate)) {
      errors.push('納期は発注日より後の日付を指定してください');
    }

    if (orderItems.length === 0) {
      errors.push('発注する商品を選択してください');
    }

    // 数量チェック
    for (const item of orderItems) {
      if (item.quantity <= 0) {
        errors.push(`${item.productName}の発注数量は1以上で入力してください`);
      }
    }

    return errors;
  }

  // エラー表示
  function showErrors(errors) {
    // 既存のエラーメッセージを削除
    container.querySelectorAll('.error-message').forEach(el => el.remove());

    if (errors.length > 0) {
      const errorDiv = document.createElement('div');
      errorDiv.className = 'error-message';
      errorDiv.innerHTML = errors.map(error => `<div>${error}</div>`).join('');
      container.querySelector('.action-buttons').insertBefore(errorDiv, container.querySelector('.action-buttons').firstChild);
      return false;
    }
    return true;
  }

  // 成功メッセージ表示
  function showSuccess(message) {
    container.querySelectorAll('.error-message, .success-message').forEach(el => el.remove());

    const successDiv = document.createElement('div');
    successDiv.className = 'success-message';
    successDiv.textContent = message;
    container.querySelector('.action-buttons').insertBefore(successDiv, container.querySelector('.action-buttons').firstChild);

    setTimeout(() => {
      successDiv.remove();
    }, 3000);
  }

  // 初期化
  initializeData();
  renderStoreOptions();
  renderProductList();

  // 今日の日付を設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector('#order-date').value = today;

  // 明日の日付を納期の初期値に設定
  const tomorrow = new Date();
  tomorrow.setDate(tomorrow.getDate() + 1);
  container.querySelector('#delivery-date').value = tomorrow.toISOString().split('T')[0];

  // カテゴリタブのイベントリスナー
  container.querySelectorAll('.category-tab').forEach(tab => {
    tab.addEventListener('click', () => {
      container.querySelectorAll('.category-tab').forEach(t => t.classList.remove('active'));
      tab.classList.add('active');
      selectedCategory = tab.dataset.category;
      renderProductList();
    });
  });

  // 商品検索
  container.querySelector('#btn-product-search').addEventListener('click', () => {
    const keyword = container.querySelector('#product-search').value.toLowerCase();
    const filtered = productData.filter(product => {
      return product.商品名?.toLowerCase().includes(keyword) || 
             product.商品コード?.toLowerCase().includes(keyword);
    });
    renderProductList(filtered);
  });

  // 商品検索（Enterキー）
  container.querySelector('#product-search').addEventListener('keypress', (e) => {
    if (e.key === 'Enter') {
      container.querySelector('#btn-product-search').click();
    }
  });

  // 発注リストに追加
  container.addEventListener('click', (e) => {
    const addBtn = e.target.closest('.add-to-order-btn');
    if (addBtn) {
      const productId = addBtn.dataset.productId;
      const product = productData.find(p => p.商品ID === productId);
      const quantityInput = container.querySelector(`input[data-product-id="${productId}"]`);
      const quantity = parseInt(quantityInput.value) || 0;

      if (quantity <= 0) {
        alert('発注数量は1以上で入力してください');
        return;
      }

      // 既に追加済みかチェック
      const existingIndex = orderItems.findIndex(item => item.productId === productId);
      if (existingIndex >= 0) {
        orderItems[existingIndex].quantity = quantity;
      } else {
        const forecast = demandForecastData.find(f => f.商品ID === productId);
        orderItems.push({
          productId: productId,
          productCode: product.商品コード,
          productName: product.商品名,
          predictedQty: forecast ? forecast.予測数量 : 0,
          quantity: quantity,
          price: product.単価 || 0
        });
      }

      renderOrderItems();
    }
  });

  // 発注リストから削除
  container.addEventListener('click', (e) => {
    const removeBtn = e.target.closest('.remove-btn');
    if (removeBtn) {
      const productId = removeBtn.dataset.productId;
      orderItems = orderItems.filter(item => item.productId !== productId);
      renderOrderItems();
    }
  });

  // 発注数量の変更
  container.addEventListener('input', (e) => {
    if (e.target.classList.contains('quantity-input') && e.target.closest('#order-items-table')) {
      const productId = e.target.dataset.productId;
      const quantity = parseInt(e.target.value) || 0;
      const item = orderItems.find(item => item.productId === productId);
      if (item) {
        item.quantity = quantity;
        updateTotalAmount();
      }
    }
  });

  // 予測根拠表示
  container.addEventListener('click', (e) => {
    const predictionBtn = e.target.closest('.prediction-btn');
    if (predictionBtn) {
      const productId = predictionBtn.dataset.productId;
      const product = productData.find(p => p.商品ID === productId);
      const forecast = demandForecastData.find(f => f.商品ID === productId);

      const modal = container.querySelector('#prediction-modal');
      const details = container.querySelector('#prediction-details');

      details.innerHTML = `
        <h4>${product.商品名}</h4>
        <div class="prediction-info">
          <p><strong>予測数量:</strong> ${forecast ? forecast.予測数量 : 0}</p>
          <p><strong>予測精度:</strong> ${forecast ? forecast.予測精度 : 0}%</p>
          <p><strong>予測モデル:</strong> ${forecast ? forecast.予測モデルバージョン : 'N/A'}</p>
          <p><strong>過去30日平均売上:</strong> 計算中...</p>
          <p><strong>季節要因:</strong> 通常期</p>
          <p><strong>トレンド:</strong> 安定</p>
        </div>
      `;

      modal.classList.remove('hidden');
    }
  });

  // モーダルを閉じる
  container.querySelector('#btn-close-modal').addEventListener('click', () => {
    container.querySelector('#prediction-modal').classList.add('hidden');
  });

  container.querySelector('#btn-close-inventory-modal').addEventListener('click', () => {
    container.querySelector('#inventory-modal').classList.add('hidden');
  });

  container.querySelector('#btn-close-history-modal').addEventListener('click', () => {
    container.querySelector('#history-modal').classList.add('hidden');
  });

  // 在庫状況確認
  container.querySelector('#btn-check-inventory').addEventListener('click', () => {
    const modal = container.querySelector('#inventory-modal');
    const details = container.querySelector('#inventory-details');

    details.innerHTML = `
      <div class="inventory-summary">
        <h4>在庫状況サマリー</h4>
        <div class="table-wrap">
          <table>
            <thead>
              <tr>
                <th>商品名</th>
                <th>現在庫</th>
                <th>安全在庫</th>
                <th>発注点</th>
                <th>リードタイム</th>
              </tr>
            </thead>
            <tbody>
              ${orderItems.map(item => `
                <tr>
                  <td>${item.productName}</td>
                  <td>計算中</td>
                  <td>計算中</td>
                  <td>計算中</td>
                  <td>3日</td>
                </tr>
              `).join('')}
            </tbody>
          </table>
        </div>
      </div>
    `;

    modal.classList.remove('hidden');
  });

  // 過去実績参照
  container.querySelector('#btn-check-history').addEventListener('click', () => {
    const modal = container.querySelector('#history-modal');
    const details = container.querySelector('#history-details');

    details.innerHTML = `
      <div class="history-summary">
        <h4>過去3ヶ月の実績</h4>
        <div class="table-wrap">
          <table>
            <thead>
              <tr>
                <th>商品名</th>
                <th>先月発注量</th>
                <th>先月売上</th>
                <th>2ヶ月前発注量</th>
                <th>2ヶ月前売上</th>
                <th>3ヶ月前発注量</th>
                <th>3ヶ月前売上</th>
              </tr>
            </thead>
            <tbody>
              ${orderItems.map(item => `
                <tr>
                  <td>${item.productName}</td>
                  <td>計算中</td>
                  <td>計算中</td>
                  <td>計算中</td>
                  <td>計算中</td>
                  <td>計算中</td>
                  <td>計算中</td>
                </tr>
              `).join('')}
            </tbody>
          </table>
        </div>
      </div>
    `;

    modal.classList.remove('hidden');
  });

  // 発注書作成
  container.querySelector('#btn-create-order').addEventListener('click', async () => {
    const errors = validateForm();
    if (!showErrors(errors)) {
      return;
    }

    const storeId = container.querySelector('#store-select').value;
    const orderDate = container.querySelector('#order-date').value;
    const deliveryDate = container.querySelector('#delivery-date').value;

    try {
      // 各商品の発注データを保存
      for (const item of orderItems) {
        const orderRecord = {
          店舗ID: storeId,
          商品ID: item.productId,
          発注日: new Date(orderDate).toISOString(),
          納期予定日: new Date(deliveryDate).toISOString(),
          発注数量: item.quantity,
          予測数量: item.predictedQty,
          発注単価: item.price,
          発注金額: item.quantity * item.price,
          発注方法: 'AI推奨採用',
          発注ステータス: '発注済',
          自動発注フラグ: false,
          作成日時: new Date().toISOString(),
          更新日時: new Date().toISOString()
        };

        const orderTableIndex = tables.findIndex(t => t.tableName === '発注データ');
        if (orderTableIndex >= 0) {
          await window.aivicApi.save(orderTableIndex, orderRecord);
        }
      }

      showSuccess('発注書が正常に作成されました');

      // フォームをリセット
      orderItems = [];
      renderOrderItems();
      container.querySelector('#store-select').value = '';
      container.querySelector('#order-date').value = today;
      container.querySelector('#delivery-date').value = tomorrow.toISOString().split('T')[0];

      // 3秒後に発注管理画面に遷移
      setTimeout(() => {
        window.showScreen('scr-1778591852463');
      }, 3000);

    } catch (error) {
      showErrors(['発注書の作成に失敗しました: ' + error.message]);
    }
  });

  // キャンセル
  container.querySelector('#btn-cancel').addEventListener('click', () => {
    if (orderItems.length > 0) {
      if (confirm('入力内容が失われますが、よろしいですか？')) {
        window.showScreen('scr-1778591852463');
      }
    } else {
      window.showScreen('scr-1778591852463');
    }
  });

  // モーダル外クリックで閉じる
  container.addEventListener('click', (e) => {
    if (e.target.classList.contains('modal')) {
      e.target.classList.add('hidden');
    }
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックス定義
  const STORE_TABLE = 1; // 店舗マスタ
  const PRODUCT_TABLE = 2; // 商品マスタ  
  const ORDER_TABLE = 7; // 発注データ
  const DEMAND_TABLE = 6; // 需要予測結果

  let currentOrders = [];
  let selectedOrderIds = new Set();

  // 今日の日付を設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector('#order-date').value = today;

  // 店舗選択肢を読み込み
  async function loadStores() {
    const stores = await window.aivicApi.list(STORE_TABLE);
    if (!stores) return;

    const storeSelect = container.querySelector('#store-select');
    storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';

    stores.filter(store => store.有効フラグ).forEach(store => {
      const option = document.createElement('option');
      option.value = store.店舗ID;
      option.textContent = `${store.店舗コード} - ${store.店舗名}`;
      storeSelect.appendChild(option);
    });
  }

  // 発注データ一覧を描画
  function renderOrderList(orders) {
    const tbody = container.querySelector('#order-tbody');

    if (!orders || orders.length === 0) {
      tbody.innerHTML = `
        <tr>
          <td colspan="8" class="muted" style="text-align: center; padding: 40px;">
            発注対象のデータがありません
          </td>
        </tr>
      `;
      updateSummary();
      return;
    }

    tbody.innerHTML = orders.map(order => {
      const isSelected = selectedOrderIds.has(order.発注ID);
      const isSent = order.発注ステータス === '送信済み';

      let statusBadge = '';
      switch(order.発注ステータス) {
        case '送信待ち':
          statusBadge = '<span class="status-badge status-pending">送信待ち</span>';
          break;
        case '送信済み':
          statusBadge = '<span class="status-badge status-sent">送信済み</span>';
          break;
        case 'エラー':
          statusBadge = '<span class="status-badge status-error">送信エラー</span>';
          break;
        default:
          statusBadge = `<span class="status-badge">${order.発注ステータス || '未設定'}</span>`;
      }

      return `
        <tr data-id="${order.発注ID}" ${isSent ? 'style="opacity: 0.6;"' : ''}>
          <td>
            <input type="checkbox" 
                   class="order-checkbox" 
                   data-id="${order.発注ID}"
                   ${isSelected ? 'checked' : ''}
                   ${isSent ? 'disabled' : ''}>
          </td>
          <td>${order.商品コード || ''}</td>
          <td>${order.商品名 || ''}</td>
          <td style="text-align: right;">${order.予測数量 || 0}</td>
          <td style="text-align: right;">${order.発注数量 || 0}</td>
          <td>${order.仕入先名 || ''}</td>
          <td class="amount-cell">¥${(order.発注金額 || 0).toLocaleString()}</td>
          <td>${statusBadge}</td>
        </tr>
      `;
    }).join('');

    updateSummary();
  }

  // 選択状況とサマリーを更新
  function updateSummary() {
    const selectedCount = selectedOrderIds.size;
    const totalAmount = currentOrders
      .filter(order => selectedOrderIds.has(order.発注ID))
      .reduce((sum, order) => sum + (order.発注金額 || 0), 0);

    container.querySelector('#selected-count').textContent = `選択: ${selectedCount}件`;
    container.querySelector('#total-amount').textContent = `合計金額: ¥${totalAmount.toLocaleString()}`;

    const sendBtn = container.querySelector('#btn-send');
    sendBtn.disabled = selectedCount === 0;

    // 全選択チェックボックスの状態更新
    const selectAllCheckbox = container.querySelector('#select-all-checkbox');
    const availableOrders = currentOrders.filter(order => order.発注ステータス !== '送信済み');
    const availableIds = availableOrders.map(order => order.発注ID);
    const selectedAvailableCount = availableIds.filter(id => selectedOrderIds.has(id)).length;

    if (availableOrders.length === 0) {
      selectAllCheckbox.indeterminate = false;
      selectAllCheckbox.checked = false;
      selectAllCheckbox.disabled = true;
    } else if (selectedAvailableCount === 0) {
      selectAllCheckbox.indeterminate = false;
      selectAllCheckbox.checked = false;
      selectAllCheckbox.disabled = false;
    } else if (selectedAvailableCount === availableIds.length) {
      selectAllCheckbox.indeterminate = false;
      selectAllCheckbox.checked = true;
      selectAllCheckbox.disabled = false;
    } else {
      selectAllCheckbox.indeterminate = true;
      selectAllCheckbox.checked = false;
      selectAllCheckbox.disabled = false;
    }
  }

  // 店舗選択時の処理
  async function loadOrdersForStore(storeId) {
    if (!storeId) {
      currentOrders = [];
      selectedOrderIds.clear();
      renderOrderList([]);
      return;
    }

    // 発注データを取得
    const orders = await window.aivicApi.list(ORDER_TABLE);
    if (!orders) {
      currentOrders = [];
      selectedOrderIds.clear();
      renderOrderList([]);
      return;
    }

    // 商品マスタを取得
    const products = await window.aivicApi.list(PRODUCT_TABLE);
    const productMap = {};
    if (products) {
      products.forEach(product => {
        productMap[product.商品ID] = product;
      });
    }

    // 需要予測結果を取得
    const demands = await window.aivicApi.list(DEMAND_TABLE);
    const demandMap = {};
    if (demands) {
      demands.forEach(demand => {
        const key = `${demand.店舗ID}_${demand.商品ID}`;
        demandMap[key] = demand;
      });
    }

    // 選択店舗の発注データをフィルタリングして拡張
    const storeOrders = orders
      .filter(order => order.店舗ID === storeId)
      .map(order => {
        const product = productMap[order.商品ID] || {};
        const demandKey = `${order.店舗ID}_${order.商品ID}`;
        const demand = demandMap[demandKey] || {};

        return {
          ...order,
          商品コード: product.商品コード,
          商品名: product.商品名,
          予測数量: demand.予測数量,
          仕入先名: product.仕入先名 || '未設定'
        };
      });

    currentOrders = storeOrders;
    selectedOrderIds.clear();
    renderOrderList(storeOrders);
  }

  // 発注送信処理
  async function sendSelectedOrders() {
    const selectedOrders = currentOrders.filter(order => selectedOrderIds.has(order.発注ID));

    if (selectedOrders.length === 0) {
      alert('発注する商品を選択してください');
      return;
    }

    // 送信済みデータの重複チェック
    const alreadySent = selectedOrders.filter(order => order.発注ステータス === '送信済み');
    if (alreadySent.length > 0) {
      alert('選択したデータに送信済みの発注が含まれています。重複送信はできません。');
      return;
    }

    // 発注数量0の商品チェック
    const zeroQuantityOrders = selectedOrders.filter(order => !order.発注数量 || order.発注数量 === 0);
    if (zeroQuantityOrders.length > 0) {
      const proceed = confirm(`発注数量が0の商品が${zeroQuantityOrders.length}件含まれています。これらを除外して送信しますか？`);
      if (!proceed) return;

      // 発注数量0の商品を除外
      zeroQuantityOrders.forEach(order => selectedOrderIds.delete(order.発注ID));
      const validOrders = selectedOrders.filter(order => order.発注数量 > 0);

      if (validOrders.length === 0) {
        alert('送信可能な発注データがありません');
        return;
      }
    }

    // 確認ダイアログ表示
    const validOrderCount = selectedOrders.filter(order => order.発注数量 > 0).length;
    const totalAmount = selectedOrders
      .filter(order => order.発注数量 > 0)
      .reduce((sum, order) => sum + (order.発注金額 || 0), 0);

    container.querySelector('#confirm-message').innerHTML = `
      ${validOrderCount}件の発注データを送信します。<br>
      合計金額: ¥${totalAmount.toLocaleString()}<br><br>
      送信しますか？
    `;
    container.querySelector('#confirm-dialog').style.display = 'flex';
  }

  // 実際の送信処理
  async function executeSend() {
    const selectedOrders = currentOrders.filter(order => 
      selectedOrderIds.has(order.発注ID) && order.発注数量 > 0
    );

    try {
      let successCount = 0;
      let errorCount = 0;

      for (const order of selectedOrders) {
        try {
          // 発注ステータスを送信済みに更新
          const updated = await window.aivicApi.update(ORDER_TABLE, order.発注ID, {
            発注ステータス: '送信済み',
            更新日時: new Date().toISOString()
          });

          if (updated) {
            successCount++;
          } else {
            errorCount++;
          }
        } catch (error) {
          console.error('発注送信エラー:', error);
          errorCount++;
        }
      }

      // 結果通知
      if (errorCount === 0) {
        alert(`${successCount}件の発注データを正常に送信しました`);
      } else {
        alert(`送信完了: ${successCount}件\n送信失敗: ${errorCount}件`);
      }

      // 画面を再読み込み
      const storeId = container.querySelector('#store-select').value;
      if (storeId) {
        await loadOrdersForStore(storeId);
      }

    } catch (error) {
      console.error('送信処理エラー:', error);
      alert('送信処理中にエラーが発生しました');
    }
  }

  // イベントリスナー設定

  // 店舗選択
  container.querySelector('#store-select').addEventListener('change', (e) => {
    loadOrdersForStore(e.target.value);
  });

  // 全選択チェックボックス
  container.querySelector('#select-all-checkbox').addEventListener('change', (e) => {
    const availableOrders = currentOrders.filter(order => order.発注ステータス !== '送信済み');

    if (e.target.checked) {
      availableOrders.forEach(order => selectedOrderIds.add(order.発注ID));
    } else {
      availableOrders.forEach(order => selectedOrderIds.delete(order.発注ID));
    }

    renderOrderList(currentOrders);
  });

  // 個別チェックボックス
  container.addEventListener('change', (e) => {
    if (e.target.classList.contains('order-checkbox')) {
      const orderId = e.target.dataset.id;

      if (e.target.checked) {
        selectedOrderIds.add(orderId);
      } else {
        selectedOrderIds.delete(orderId);
      }

      updateSummary();
    }
  });

  // 送信ボタン
  container.querySelector('#btn-send').addEventListener('click', sendSelectedOrders);

  // 戻るボタン
  container.querySelector('#btn-back').addEventListener('click', () => {
    window.showScreen('scr-1778591852463'); // 発注管理画面
  });

  // 確認ダイアログ
  container.querySelector('#btn-confirm-ok').addEventListener('click', () => {
    container.querySelector('#confirm-dialog').style.display = 'none';
    executeSend();
  });

  container.querySelector('#btn-confirm-cancel').addEventListener('click', () => {
    container.querySelector('#confirm-dialog').style.display = 'none';
  });

  // 初期化
  loadStores();
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#results-tbody");
  const errorDiv = container.querySelector("#error-message");

  // エラー表示関数
  function showError(message) {
    errorDiv.textContent = message;
    errorDiv.classList.remove("hidden");
  }

  function hideError() {
    errorDiv.classList.add("hidden");
  }

  // 店舗データを読み込んでドロップダウンに設定
  async function loadStores() {
    const stores = await window.aivicApi.list(1); // 店舗マスタ
    const storeSelect = container.querySelector("#store-select");
    if (stores) {
      stores.forEach(store => {
        const option = document.createElement("option");
        option.value = store.id;
        option.textContent = `${store.店舗名} (${store.店舗コード})`;
        storeSelect.appendChild(option);
      });
    }
  }

  // 計算結果テーブル再描画関数
  function renderResults(results) {
    tbody.innerHTML = results.map(r => `
      <tr data-id="${r.id}">
        <td><a href="#" class="product-detail-link" data-id="${r.商品ID}" style="color: var(--primary); text-decoration: none;">${r.商品名 || ""}</a></td>
        <td>${r.商品コード || ""}</td>
        <td>${r.現在在庫 || 0}</td>
        <td>${r.予測需要量 || 0}</td>
        <td>${r.安全在庫 || 0}</td>
        <td>${r.リードタイム || 0}日</td>
        <td>${r.発注点 || 0}</td>
        <td style="font-weight: bold; color: var(--primary);">${r.推奨発注量 || 0}</td>
        <td>¥${(r.発注金額 || 0).toLocaleString()}</td>
        <td>
          <button class="action-btn secondary detail-btn" data-id="${r.id}">詳細</button>
          <button class="action-btn secondary order-btn" data-id="${r.id}">発注</button>
        </td>
      </tr>
    `).join("");
  }

  // 初期データ表示
  renderResults(tables[8]?.records || []); // 需要予測結果テーブル

  // 店舗データ読み込み
  loadStores();

  // 計算実行ボタン
  container.querySelector("#btn-calculate").addEventListener("click", async () => {
    hideError();

    const storeId = container.querySelector("#store-select").value;
    const category = container.querySelector("#category-select").value;
    const periodStart = container.querySelector("#period-start").value;
    const periodEnd = container.querySelector("#period-end").value;
    const safetyStock = parseInt(container.querySelector("#safety-stock").value) || 0;
    const leadTime = parseInt(container.querySelector("#lead-time").value) || 0;
    const reorderPoint = parseInt(container.querySelector("#reorder-point").value) || 0;

    // バリデーション
    if (!storeId) {
      showError("店舗を選択してください");
      return;
    }
    if (!category) {
      showError("商品カテゴリを選択してください");
      return;
    }
    if (!periodStart || !periodEnd) {
      showError("計算対象期間を設定してください");
      return;
    }
    if (safetyStock < 0) {
      showError("安全在庫数は0以上の値を入力してください");
      return;
    }
    if (leadTime <= 0) {
      showError("リードタイムは1以上の値を入力してください");
      return;
    }
    if (reorderPoint < 0) {
      showError("発注点は0以上の値を入力してください");
      return;
    }

    try {
      // 需要予測データ取得
      const forecasts = await window.aivicApi.list(8); // 需要予測結果
      if (!forecasts) {
        showError("需要予測データの取得に失敗しました");
        return;
      }

      // 商品マスタ取得
      const products = await window.aivicApi.list(2); // 商品マスタ
      if (!products) {
        showError("商品データの取得に失敗しました");
        return;
      }

      // 在庫データ取得（売上実績から推定）
      const salesData = await window.aivicApi.list(3); // 売上実績データ
      if (!salesData) {
        showError("在庫データの取得に失敗しました");
        return;
      }

      // カテゴリでフィルタリングした商品を取得
      const categoryProducts = products.filter(p => 
        p.商品カテゴリ && p.商品カテゴリ.includes(category) && p.有効フラグ
      );

      if (categoryProducts.length === 0) {
        showError("選択されたカテゴリに該当する商品が見つかりません");
        return;
      }

      // 計算結果生成
      const calculationResults = categoryProducts.map(product => {
        const productForecasts = forecasts.filter(f => 
          f.商品ID === product.id && f.店舗ID === storeId
        );

        const avgForecast = productForecasts.length > 0 
          ? Math.round(productForecasts.reduce((sum, f) => sum + (f.予測数量 || 0), 0) / productForecasts.length)
          : 0;

        // 現在在庫を売上データから推定（簡易計算）
        const recentSales = salesData.filter(s => 
          s.商品ID === product.id && s.店舗ID === storeId
        );
        const avgSales = recentSales.length > 0 
          ? Math.round(recentSales.reduce((sum, s) => sum + (s.販売数量 || 0), 0) / recentSales.length * 7)
          : Math.floor(Math.random() * 100) + 50; // ダミーデータ

        const currentStock = Math.max(0, avgSales - Math.floor(Math.random() * 30));

        // 発注量計算
        const demandDuringLeadTime = Math.ceil(avgForecast * (leadTime / 7));
        const recommendedOrder = Math.max(0, 
          (reorderPoint || demandDuringLeadTime) + safetyStock - currentStock
        );

        const orderAmount = recommendedOrder * (product.単価 || 0);

        return {
          id: `calc_${product.id}_${Date.now()}`,
          商品ID: product.id,
          商品名: product.商品名,
          商品コード: product.商品コード,
          現在在庫: currentStock,
          予測需要量: avgForecast,
          安全在庫: safetyStock,
          リードタイム: leadTime,
          発注点: reorderPoint || demandDuringLeadTime,
          推奨発注量: recommendedOrder,
          発注金額: orderAmount
        };
      });

      // 結果表示
      renderResults(calculationResults);

      // サマリー更新
      const totalCurrentStock = calculationResults.reduce((sum, r) => sum + r.現在在庫, 0);
      const totalRecommendedOrder = calculationResults.reduce((sum, r) => sum + r.推奨発注量, 0);
      const totalForecastDemand = calculationResults.reduce((sum, r) => sum + r.予測需要量, 0);

      container.querySelector("#current-stock").textContent = totalCurrentStock.toLocaleString();
      container.querySelector("#recommended-order").textContent = totalRecommendedOrder.toLocaleString();
      container.querySelector("#forecast-demand").textContent = totalForecastDemand.toLocaleString();

      // 需要予測結果表示更新
      const forecastDisplay = container.querySelector("#forecast-display");
      forecastDisplay.innerHTML = `
        <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 12px;">
          <div>
            <div style="color: var(--text-muted); font-size: 0.9em;">対象商品数</div>
            <div style="font-size: 1.2em; font-weight: bold; color: var(--text);">${calculationResults.length}商品</div>
          </div>
          <div>
            <div style="color: var(--text-muted); font-size: 0.9em;">計算期間</div>
            <div style="font-size: 1.2em; font-weight: bold; color: var(--text);">${periodStart} ～ ${periodEnd}</div>
          </div>
          <div>
            <div style="color: var(--text-muted); font-size: 0.9em;">総発注金額</div>
            <div style="font-size: 1.2em; font-weight: bold; color: var(--primary);">¥${calculationResults.reduce((sum, r) => sum + r.発注金額, 0).toLocaleString()}</div>
          </div>
        </div>
      `;

    } catch (error) {
      showError("計算処理中にエラーが発生しました: " + error.message);
    }
  });

  // クリアボタン
  container.querySelector("#btn-clear").addEventListener("click", () => {
    container.querySelector("#store-select").value = "";
    container.querySelector("#category-select").value = "";
    container.querySelector("#period-start").value = "";
    container.querySelector("#period-end").value = "";
    container.querySelector("#safety-stock").value = "";
    container.querySelector("#lead-time").value = "";
    container.querySelector("#reorder-point").value = "";

    container.querySelector("#current-stock").textContent = "-";
    container.querySelector("#recommended-order").textContent = "-";
    container.querySelector("#forecast-demand").textContent = "-";

    const forecastDisplay = container.querySelector("#forecast-display");
    forecastDisplay.innerHTML = '<p class="muted">計算実行後に需要予測結果が表示されます</p>';

    renderResults([]);
    hideError();
  });

  // 検索機能
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const keyword = container.querySelector("#input-search").value.toLowerCase();
    const currentRows = Array.from(tbody.querySelectorAll("tr")).map(tr => {
      const cells = tr.querySelectorAll("td");
      return {
        id: tr.dataset.id,
        商品名: cells[0]?.textContent || "",
        商品コード: cells[1]?.textContent || "",
        現在在庫: parseInt(cells[2]?.textContent) || 0,
        予測需要量: parseInt(cells[3]?.textContent) || 0,
        安全在庫: parseInt(cells[4]?.textContent) || 0,
        リードタイム: parseInt(cells[5]?.textContent) || 0,
        発注点: parseInt(cells[6]?.textContent) || 0,
        推奨発注量: parseInt(cells[7]?.textContent) || 0,
        発注金額: parseInt(cells[8]?.textContent.replace(/[¥,]/g, "")) || 0
      };
    });

    const filteredRows = currentRows.filter(row => 
      row.商品名.toLowerCase().includes(keyword) || 
      row.商品コード.toLowerCase().includes(keyword)
    );

    renderResults(filteredRows);
  });

  // CSVエクスポート
  container.querySelector("#btn-export").addEventListener("click", () => {
    const rows = Array.from(tbody.querySelectorAll("tr")).map(tr => {
      const cells = tr.querySelectorAll("td");
      return [
        cells[0]?.textContent || "",
        cells[1]?.textContent || "",
        cells[2]?.textContent || "",
        cells[3]?.textContent || "",
        cells[4]?.textContent || "",
        cells[5]?.textContent || "",
        cells[6]?.textContent || "",
        cells[7]?.textContent || "",
        cells[8]?.textContent || ""
      ];
    });

    const headers = ["商品名", "商品コード", "現在在庫", "予測需要量", "安全在庫", "リードタイム", "発注点", "推奨発注量", "発注金額"];
    const csvContent = "\uFEFF" + [headers, ...rows].map(row => 
      row.map(cell => `"${cell}"`).join(",")
    ).join("\n");

    const blob = new Blob([csvContent], { type: "text/csv" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `発注量計算結果_${new Date().toISOString().split('T')[0]}.csv`;
    a.click();
    URL.revokeObjectURL(url);
  });

  // 行レベル操作（イベントデリゲーション）
  container.addEventListener("click", async (e) => {
    // 商品詳細リンク
    const productLink = e.target.closest(".product-detail-link");
    if (productLink) {
      e.preventDefault();
      // 商品詳細画面への遷移（実装されている場合）
      console.log("商品詳細:", productLink.dataset.id);
      return;
    }

    // 詳細ボタン
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      const row = detailBtn.closest("tr");
      const productName = row.querySelector("td").textContent;
      alert(`${productName}の詳細情報を表示します`);
      return;
    }

    // 発注ボタン
    const orderBtn = e.target.closest(".order-btn");
    if (orderBtn) {
      const row = orderBtn.closest("tr");
      const cells = row.querySelectorAll("td");
      const productName = cells[0].textContent;
      const recommendedOrder = cells[7].textContent;

      if (confirm(`${productName}を${recommendedOrder}個発注しますか？`)) {
        // 発注処理画面に遷移
        window.showScreen("scr-1778591960771"); // 発注実行画面
      }
      return;
    }
  });
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#inventory-tbody");
  const storeSelect = container.querySelector("#store-select");
  const categoryFilter = container.querySelector("#category-filter");
  const productNameSearch = container.querySelector("#product-name-search");
  const productCodeSearch = container.querySelector("#product-code-search");
  const stockStatusFilter = container.querySelector("#stock-status-filter");
  const errorMessage = container.querySelector("#error-message");
  const resultCount = container.querySelector("#result-count");
  const noResults = container.querySelector("#no-results");

  let allInventoryData = [];
  let storeData = [];
  let productData = [];

  // エラーメッセージ表示関数
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.classList.remove("hidden");
    setTimeout(() => {
      errorMessage.classList.add("hidden");
    }, 5000);
  }

  // 在庫状況判定関数
  function getStockStatus(currentStock, safetyStock) {
    if (currentStock <= 0) return "不足";
    if (currentStock <= safetyStock) return "不足";
    if (currentStock > safetyStock * 2) return "過剰";
    return "適正";
  }

  // 在庫状況のスタイル取得
  function getStatusStyle(status) {
    switch(status) {
      case "不足":
        return "background: rgba(255, 106, 106, 0.1); color: #ff6a6a; padding: 4px 8px; border-radius: 4px; font-size: 12px; font-weight: 500;";
      case "過剰":
        return "background: rgba(255, 165, 0, 0.1); color: #ffa500; padding: 4px 8px; border-radius: 4px; font-size: 12px; font-weight: 500;";
      case "適正":
        return "background: rgba(34, 197, 94, 0.1); color: #22c55e; padding: 4px 8px; border-radius: 4px; font-size: 12px; font-weight: 500;";
      default:
        return "color: var(--text-muted);";
    }
  }

  // 在庫テーブル再描画関数
  function renderInventoryRows(inventoryRows) {
    if (!inventoryRows || inventoryRows.length === 0) {
      tbody.innerHTML = "";
      resultCount.textContent = "";
      noResults.classList.remove("hidden");
      return;
    }

    noResults.classList.add("hidden");
    resultCount.textContent = `検索結果: ${inventoryRows.length}件`;

    tbody.innerHTML = inventoryRows.map(row => {
      const product = productData.find(p => p.商品ID === row.商品ID) || {};
      const currentStock = row.現在在庫数 || 0;
      const safetyStock = row.安全在庫数 || 0;
      const status = getStockStatus(currentStock, safetyStock);
      const statusStyle = getStatusStyle(status);

      return `
        <tr data-id="${row.在庫ID || row.id || ''}">
          <td style="color: var(--text);">${product.商品コード || row.商品コード || ''}</td>
          <td style="color: var(--text);">${product.商品名 || row.商品名 || ''}</td>
          <td style="color: var(--text); text-align: right;">${currentStock.toLocaleString()}</td>
          <td style="color: var(--text); text-align: right;">${safetyStock.toLocaleString()}</td>
          <td><span style="${statusStyle}">${status}</span></td>
          <td style="color: var(--text-muted); font-size: 12px;">${row.更新日時 ? new Date(row.更新日時).toLocaleString() : ''}</td>
        </tr>
      `;
    }).join("");
  }

  // 店舗選択肢を設定
  function populateStoreOptions() {
    if (storeData && storeData.length > 0) {
      storeSelect.innerHTML = '<option value="">店舗を選択してください</option>' +
        storeData.filter(store => store.有効フラグ).map(store => 
          `<option value="${store.店舗ID}">${store.店舗名}</option>`
        ).join("");
    }
  }

  // 検索フィルター適用
  function applyFilters() {
    const selectedStoreId = storeSelect.value;
    const selectedCategory = categoryFilter.value;
    const productNameKeyword = productNameSearch.value.trim().toLowerCase();
    const productCodeKeyword = productCodeSearch.value.trim();
    const selectedStatus = stockStatusFilter.value;

    // 店舗未選択チェック
    if (!selectedStoreId) {
      showError("店舗を選択してください");
      return;
    }

    // 商品名の特殊文字チェック
    if (productNameKeyword && /<script|javascript:|data:|vbscript:|onload=|onerror=/i.test(productNameKeyword)) {
      showError("商品名に不正な文字が含まれています");
      return;
    }

    // 商品コードの文字チェック（数値以外が含まれている場合）
    if (productCodeKeyword && !/^[A-Za-z0-9\-_]*$/.test(productCodeKeyword)) {
      showError("商品コードは英数字で入力してください");
      return;
    }

    // 商品名の最大文字数チェック
    if (productNameKeyword.length > 255) {
      showError("商品名は255文字以内で入力してください");
      return;
    }

    // 商品コードの最大桁数チェック
    if (productCodeKeyword.length > 20) {
      showError("商品コードは20文字以内で入力してください");
      return;
    }

    let filteredData = allInventoryData.filter(row => {
      // 店舗フィルター
      if (row.店舗ID !== selectedStoreId) return false;

      const product = productData.find(p => p.商品ID === row.商品ID) || {};

      // カテゴリフィルター
      if (selectedCategory && product.商品カテゴリ !== selectedCategory) return false;

      // 商品名検索
      if (productNameKeyword) {
        const productName = (product.商品名 || '').toLowerCase();
        if (!productName.includes(productNameKeyword)) return false;
      }

      // 商品コード検索
      if (productCodeKeyword) {
        const productCode = product.商品コード || '';
        if (!productCode.includes(productCodeKeyword)) return false;
      }

      // 在庫状況フィルター
      if (selectedStatus) {
        const currentStock = row.現在在庫数 || 0;
        const safetyStock = row.安全在庫数 || 0;
        const status = getStockStatus(currentStock, safetyStock);
        if (status !== selectedStatus) return false;
      }

      return true;
    });

    renderInventoryRows(filteredData);
  }

  // 検索条件クリア
  function clearFilters() {
    storeSelect.value = "";
    categoryFilter.value = "";
    productNameSearch.value = "";
    productCodeSearch.value = "";
    stockStatusFilter.value = "";
    tbody.innerHTML = "";
    resultCount.textContent = "";
    noResults.classList.add("hidden");
    errorMessage.classList.add("hidden");
  }

  // CSVエクスポート
  function exportCSV() {
    const selectedStoreId = storeSelect.value;
    if (!selectedStoreId) {
      showError("店舗を選択してください");
      return;
    }

    const filteredData = allInventoryData.filter(row => row.店舗ID === selectedStoreId);

    if (filteredData.length === 0) {
      showError("エクスポートするデータがありません");
      return;
    }

    const headers = ["商品コード", "商品名", "現在在庫数", "安全在庫数", "在庫状況", "最終更新日時"];
    const csvRows = [headers.join(",")];

    filteredData.forEach(row => {
      const product = productData.find(p => p.商品ID === row.商品ID) || {};
      const currentStock = row.現在在庫数 || 0;
      const safetyStock = row.安全在庫数 || 0;
      const status = getStockStatus(currentStock, safetyStock);
      const updateDate = row.更新日時 ? new Date(row.更新日時).toLocaleString() : "";

      const csvRow = [
        `"${product.商品コード || ''}"`,
        `"${product.商品名 || ''}"`,
        currentStock,
        safetyStock,
        `"${status}"`,
        `"${updateDate}"`
      ];
      csvRows.push(csvRow.join(","));
    });

    const csvContent = "\uFEFF" + csvRows.join("\n");
    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    const url = URL.createObjectURL(blob);
    link.setAttribute("href", url);
    link.setAttribute("download", `inventory_${new Date().toISOString().split('T')[0]}.csv`);
    link.style.visibility = "hidden";
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      // 店舗データ読み込み
      const stores = await window.aivicApi.list(1); // 店舗マスタ
      if (stores) {
        storeData = stores;
        populateStoreOptions();
      }

      // 商品データ読み込み
      const products = await window.aivicApi.list(2); // 商品マスタ
      if (products) {
        productData = products;
      }

      // 在庫データの代わりに売上実績データを使用（在庫テーブルが存在しないため）
      const salesData = await window.aivicApi.list(3); // 売上実績データ
      if (salesData) {
        // 売上実績データから在庫データを模擬生成
        const inventoryMap = new Map();

        salesData.forEach(sale => {
          const key = `${sale.店舗ID}_${sale.商品ID}`;
          if (!inventoryMap.has(key)) {
            const product = productData.find(p => p.商品ID === sale.商品ID);
            inventoryMap.set(key, {
              在庫ID: `inv_${sale.店舗ID}_${sale.商品ID}`,
              店舗ID: sale.店舗ID,
              商品ID: sale.商品ID,
              商品コード: product?.商品コード || '',
              商品名: product?.商品名 || '',
              現在在庫数: Math.floor(Math.random() * 100) + 10,
              安全在庫数: Math.floor(Math.random() * 30) + 5,
              更新日時: new Date().toISOString()
            });
          }
        });

        allInventoryData = Array.from(inventoryMap.values());
      }

    } catch (error) {
      console.error("データ読み込みエラー:", error);
      showError("データの読み込みに失敗しました");
    }
  }

  // イベントリスナー登録
  container.querySelector("#btn-search").addEventListener("click", applyFilters);
  container.querySelector("#btn-clear").addEventListener("click", clearFilters);
  container.querySelector("#btn-export").addEventListener("click", exportCSV);

  // 初期データ読み込み実行
  loadInitialData();
}

function(container, apiUrl, tables) {
  // テーブルインデックス定義
  const STORES_TABLE = 1;
  const PRODUCTS_TABLE = 2;
  const DEMAND_FORECAST_TABLE = 9;
  const ORDER_TABLE = 11;

  let currentStoreId = '';
  let currentOrderDate = '';
  let currentCategoryFilter = '';
  let orderItems = [];
  let selectedItems = new Set();

  // 今日の日付を設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector('#order-date').value = today;
  currentOrderDate = today;

  // エラーメッセージ表示関数
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
    setTimeout(() => {
      errorDiv.classList.add('hidden');
    }, 5000);
  }

  // 成功メッセージ表示関数
  function showSuccess(message) {
    const successDiv = container.querySelector('#order-success-message');
    successDiv.textContent = message;
    successDiv.classList.remove('hidden');
    setTimeout(() => {
      successDiv.classList.add('hidden');
    }, 3000);
  }

  // 店舗ドロップダウン初期化
  async function initStoreDropdown() {
    try {
      const stores = await window.aivicApi.list(STORES_TABLE);
      const storeSelect = container.querySelector('#store-select');

      if (stores && stores.length > 0) {
        stores.filter(store => store.有効フラグ).forEach(store => {
          const option = document.createElement('option');
          option.value = store.店舗ID;
          option.textContent = `${store.店舗コード} - ${store.店舗名}`;
          storeSelect.appendChild(option);
        });
      }
    } catch (error) {
      console.error('店舗データの取得に失敗しました:', error);
    }
  }

  // カテゴリフィルター初期化
  async function initCategoryFilter() {
    try {
      const products = await window.aivicApi.list(PRODUCTS_TABLE);
      const categorySelect = container.querySelector('#category-filter');

      if (products && products.length > 0) {
        const categories = [...new Set(products.map(p => p.商品カテゴリID))];
        categories.forEach(categoryId => {
          if (categoryId) {
            const option = document.createElement('option');
            option.value = categoryId;
            option.textContent = `カテゴリ ${categoryId}`;
            categorySelect.appendChild(option);
          }
        });
      }
    } catch (error) {
      console.error('カテゴリデータの取得に失敗しました:', error);
    }
  }

  // 発注アイテム一覧再描画
  function renderOrderItems(items) {
    const tbody = container.querySelector('#order-items-tbody');

    if (!items || items.length === 0) {
      tbody.innerHTML = `
        <tr>
          <td colspan="10" style="text-align: center; padding: 40px; color: var(--text-muted);">
            ${currentStoreId ? 'データがありません' : '店舗を選択してください'}
          </td>
        </tr>
      `;
      return;
    }

    tbody.innerHTML = items.map(item => `
      <tr data-id="${item.商品ID}">
        <td style="text-align: center;">
          <input type="checkbox" class="item-checkbox" data-id="${item.商品ID}" ${selectedItems.has(item.商品ID) ? 'checked' : ''}>
        </td>
        <td>${item.商品コード || ''}</td>
        <td>${item.商品名 || ''}</td>
        <td style="text-align: right;">${item.予測数量 || 0}</td>
        <td style="text-align: right;">${item.推奨発注数量 || 0}</td>
        <td style="text-align: right;">${item.現在在庫数量 || 0}</td>
        <td>
          <input type="number" class="input order-quantity-input" data-id="${item.商品ID}" 
                 value="${item.発注数量 || item.推奨発注数量 || 0}" min="0" max="99999" 
                 style="width: 100px; text-align: right;">
        </td>
        <td style="text-align: right;">¥${(item.単価 || 0).toLocaleString()}</td>
        <td style="text-align: right;" class="order-amount" data-id="${item.商品ID}">
          ¥${((item.発注数量 || item.推奨発注数量 || 0) * (item.単価 || 0)).toLocaleString()}
        </td>
        <td>
          <button class="action-btn secondary single-order-btn" data-id="${item.商品ID}">発注</button>
        </td>
      </tr>
    `).join('');

    updateTotalAmount();
    updateBulkOrderButton();
  }

  // 合計金額更新
  function updateTotalAmount() {
    let total = 0;
    const selectedItemsArray = Array.from(selectedItems);

    selectedItemsArray.forEach(itemId => {
      const item = orderItems.find(i => i.商品ID === itemId);
      const quantityInput = container.querySelector(`input[data-id="${itemId}"]`);
      if (item && quantityInput) {
        const quantity = parseInt(quantityInput.value) || 0;
        total += quantity * (item.単価 || 0);
      }
    });

    container.querySelector('#total-amount').textContent = `合計金額: ¥${total.toLocaleString()}`;
  }

  // まとめて発注ボタンの状態更新
  function updateBulkOrderButton() {
    const bulkOrderBtn = container.querySelector('#btn-bulk-order');
    bulkOrderBtn.disabled = selectedItems.size === 0;
  }

  // 発注データ取得
  async function loadOrderItems() {
    if (!currentStoreId) {
      renderOrderItems([]);
      return;
    }

    try {
      // 需要予測結果を取得
      const forecasts = await window.aivicApi.list(DEMAND_FORECAST_TABLE);
      const products = await window.aivicApi.list(PRODUCTS_TABLE);

      if (!forecasts || !products) {
        renderOrderItems([]);
        return;
      }

      // 店舗・日付でフィルタリング
      const targetDate = new Date(currentOrderDate);
      const filteredForecasts = forecasts.filter(f => {
        const forecastDate = new Date(f.予測対象日);
        return f.店舗ID === currentStoreId && 
               forecastDate.toDateString() === targetDate.toDateString();
      });

      // 商品情報と結合
      const items = filteredForecasts.map(forecast => {
        const product = products.find(p => p.商品ID === forecast.商品ID);
        if (!product) return null;

        // カテゴリフィルター適用
        if (currentCategoryFilter && product.商品カテゴリID !== currentCategoryFilter) {
          return null;
        }

        return {
          商品ID: product.商品ID,
          商品コード: product.商品コード,
          商品名: product.商品名,
          予測数量: forecast.予測数量,
          推奨発注数量: forecast.推奨発注数量,
          現在在庫数量: Math.floor(Math.random() * 100), // 仮の在庫数
          単価: product.単価,
          発注数量: forecast.推奨発注数量
        };
      }).filter(item => item !== null);

      orderItems = items;
      renderOrderItems(items);

    } catch (error) {
      console.error('発注データの取得に失敗しました:', error);
      showError('発注データの取得に失敗しました');
    }
  }

  // バリデーション
  function validateOrderData(items) {
    const errors = [];

    if (!currentStoreId) {
      errors.push('店舗を選択してください');
    }

    if (!currentOrderDate) {
      errors.push('発注日付を選択してください');
    } else {
      const orderDate = new Date(currentOrderDate);
      const today = new Date();
      today.setHours(0, 0, 0, 0);
      if (orderDate < today) {
        errors.push('発注日付は本日以降の日付を選択してください');
      }
    }

    if (items.length === 0) {
      errors.push('発注する商品を選択してください');
    }

    for (const item of items) {
      const quantity = item.発注数量;

      if (quantity === undefined || quantity === null || quantity === '') {
        errors.push(`${item.商品名}: 発注数量を入力してください`);
      } else if (isNaN(quantity)) {
        errors.push(`${item.商品名}: 発注数量は数値を入力してください`);
      } else if (quantity < 0) {
        errors.push(`${item.商品名}: 発注数量は正の値を入力してください`);
      } else if (quantity === 0) {
        errors.push(`${item.商品名}: 発注数量は1以上の値を入力してください`);
      } else if (quantity % 1 !== 0) {
        errors.push(`${item.商品名}: 発注数量は整数を入力してください`);
      } else if (quantity > 99999) {
        errors.push(`${item.商品名}: 発注数量は99999以下で入力してください`);
      }
    }

    return errors;
  }

  // 発注確認ダイアログ表示
  function showOrderConfirmDialog(items) {
    const dialog = container.querySelector('#order-confirm-dialog');
    const content = container.querySelector('#order-confirm-content');

    const totalAmount = items.reduce((sum, item) => sum + (item.発注数量 * item.単価), 0);

    content.innerHTML = `
      <div style="margin-bottom: 15px;">
        <strong>店舗:</strong> ${container.querySelector('#store-select option:checked').textContent}<br>
        <strong>発注日:</strong> ${currentOrderDate}<br>
        <strong>発注商品数:</strong> ${items.length}件<br>
        <strong>合計金額:</strong> ¥${totalAmount.toLocaleString()}
      </div>
      <div style="max-height: 300px; overflow-y: auto; border: 1px solid var(--border); border-radius: 4px;">
        <table style="width: 100%; font-size: 14px;">
          <thead>
            <tr style="background: var(--bg-main);">
              <th style="padding: 8px; color: var(--text);">商品名</th>
              <th style="padding: 8px; color: var(--text); text-align: right;">数量</th>
              <th style="padding: 8px; color: var(--text); text-align: right;">単価</th>
              <th style="padding: 8px; color: var(--text); text-align: right;">金額</th>
            </tr>
          </thead>
          <tbody>
            ${items.map(item => `
              <tr>
                <td style="padding: 8px; color: var(--text);">${item.商品名}</td>
                <td style="padding: 8px; color: var(--text); text-align: right;">${item.発注数量}</td>
                <td style="padding: 8px; color: var(--text); text-align: right;">¥${item.単価.toLocaleString()}</td>
                <td style="padding: 8px; color: var(--text); text-align: right;">¥${(item.発注数量 * item.単価).toLocaleString()}</td>
              </tr>
            `).join('')}
          </tbody>
        </table>
      </div>
    `;

    dialog.classList.remove('hidden');
  }

  // 発注実行
  async function executeOrder(items) {
    try {
      const orders = items.map(item => ({
        店舗ID: currentStoreId,
        商品ID: item.商品ID,
        発注日: currentOrderDate + 'T00:00:00Z',
        納期予定日: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(),
        発注数量: item.発注数量,
        予測数量: item.予測数量,
        発注単価: item.単価,
        発注金額: item.発注数量 * item.単価,
        発注方法: 'AI推奨採用',
        発注ステータス: '発注済',
        仕入先ID: 'supplier-001',
        発注理由: 'AI需要予測に基づく発注',
        自動発注フラグ: false,
        作成日時: new Date().toISOString(),
        更新日時: new Date().toISOString(),
        作成者ID: 'current-user',
        更新者ID: 'current-user'
      }));

      // 各発注を個別に保存
      for (const order of orders) {
        await window.aivicApi.save(ORDER_TABLE, order);
      }

      // 成功メッセージ表示
      showSuccess(`${items.length}件の商品を発注しました`);

      // 選択状態をクリア
      selectedItems.clear();

      // データを再読み込み
      await loadOrderItems();

    } catch (error) {
      console.error('発注処理に失敗しました:', error);
      showError('発注処理に失敗しました');
    }
  }

  // イベントリスナー設定

  // 店舗選択
  container.querySelector('#store-select').addEventListener('change', async (e) => {
    currentStoreId = e.target.value;
    selectedItems.clear();
    await loadOrderItems();
  });

  // 発注日付選択
  container.querySelector('#order-date').addEventListener('change', async (e) => {
    currentOrderDate = e.target.value;
    await loadOrderItems();
  });

  // カテゴリフィルター
  container.querySelector('#category-filter').addEventListener('change', async (e) => {
    currentCategoryFilter = e.target.value;
    await loadOrderItems();
  });

  // 検索・更新ボタン
  container.querySelector('#btn-search').addEventListener('click', async () => {
    await loadOrderItems();
  });

  // 全選択チェックボックス
  container.querySelector('#select-all-checkbox').addEventListener('change', (e) => {
    const checkboxes = container.querySelectorAll('.item-checkbox');
    checkboxes.forEach(cb => {
      cb.checked = e.target.checked;
      if (e.target.checked) {
        selectedItems.add(cb.dataset.id);
      } else {
        selectedItems.delete(cb.dataset.id);
      }
    });
    container.querySelector('#selected-count').textContent = `選択: ${selectedItems.size}件`;
    updateTotalAmount();
    updateBulkOrderButton();
  });

  // まとめて発注実行ボタン
  container.querySelector('#btn-bulk-order').addEventListener('click', () => {
    const selectedOrderItems = [];

    selectedItems.forEach(itemId => {
      const item = orderItems.find(i => i.商品ID === itemId);
      const quantityInput = container.querySelector(`input[data-id="${itemId}"]`);

      if (item && quantityInput) {
        const quantity = parseInt(quantityInput.value) || 0;
        selectedOrderItems.push({
          ...item,
          発注数量: quantity
        });
      }
    });

    const errors = validateOrderData(selectedOrderItems);
    if (errors.length > 0) {
      showError(errors.join('\n'));
      return;
    }

    showOrderConfirmDialog(selectedOrderItems);
  });

  // 発注確認ダイアログのイベント
  container.querySelector('#btn-cancel-order').addEventListener('click', () => {
    container.querySelector('#order-confirm-dialog').classList.add('hidden');
  });

  container.querySelector('#btn-execute-order').addEventListener('click', async () => {
    container.querySelector('#order-confirm-dialog').classList.add('hidden');

    const selectedOrderItems = [];
    selectedItems.forEach(itemId => {
      const item = orderItems.find(i => i.商品ID === itemId);
      const quantityInput = container.querySelector(`input[data-id="${itemId}"]`);

      if (item && quantityInput) {
        const quantity = parseInt(quantityInput.value) || 0;
        selectedOrderItems.push({
          ...item,
          発注数量: quantity
        });
      }
    });

    await executeOrder(selectedOrderItems);
  });

  // イベントデリゲーション
  container.addEventListener('change', (e) => {
    // 個別チェックボックス
    if (e.target.classList.contains('item-checkbox')) {
      const itemId = e.target.dataset.id;
      if (e.target.checked) {
        selectedItems.add(itemId);
      } else {
        selectedItems.delete(itemId);
      }

      container.querySelector('#selected-count').textContent = `選択: ${selectedItems.size}件`;

      // 全選択チェックボックスの状態更新
      const allCheckboxes = container.querySelectorAll('.item-checkbox');
      const checkedCount = container.querySelectorAll('.item-checkbox:checked').length;
      const selectAllCheckbox = container.querySelector('#select-all-checkbox');
      selectAllCheckbox.checked = checkedCount === allCheckboxes.length;
      selectAllCheckbox.indeterminate = checkedCount > 0 && checkedCount < allCheckboxes.length;

      updateTotalAmount();
      updateBulkOrderButton();
    }

    // 発注数量入力
    if (e.target.classList.contains('order-quantity-input')) {
      const itemId = e.target.dataset.id;
      const quantity = parseInt(e.target.value) || 0;
      const item = orderItems.find(i => i.商品ID === itemId);

      if (item) {
        const amount = quantity * item.単価;
        const amountCell = container.querySelector(`.order-amount[data-id="${itemId}"]`);
        if (amountCell) {
          amountCell.textContent = `¥${amount.toLocaleString()}`;
        }
      }

      updateTotalAmount();
    }
  });

  container.addEventListener('click', async (e) => {
    // 個別発注ボタン
    if (e.target.classList.contains('single-order-btn')) {
      const itemId = e.target.dataset.id;
      const item = orderItems.find(i => i.商品ID === itemId);
      const quantityInput = container.querySelector(`input[data-id="${itemId}"]`);

      if (item && quantityInput) {
        const quantity = parseInt(quantityInput.value) || 0;
        const orderItem = {
          ...item,
          発注数量: quantity
        };

        const errors = validateOrderData([orderItem]);
        if (errors.length > 0) {
          showError(errors.join('\n'));
          return;
        }

        showOrderConfirmDialog([orderItem]);
      }
    }
  });

  // 初期化
  initStoreDropdown();
  initCategoryFilter();
}

function(container, apiUrl, tables) {
  let currentData = [];
  let sortColumn = '';
  let sortDirection = 'asc';

  // 店舗データを取得してドロップダウンに設定
  async function loadStores() {
    try {
      const stores = await window.aivicApi.list(1); // 店舗マスタのインデックス
      const storeSelect = container.querySelector('#select-store');
      if (stores) {
        stores.forEach(store => {
          const option = document.createElement('option');
          option.value = store.id;
          option.textContent = store.店舗名 || store.storeName || `店舗${store.id}`;
          storeSelect.appendChild(option);
        });
      }
    } catch (error) {
      console.error('店舗データの読み込みに失敗しました:', error);
    }
  }

  // 予測精度データの再描画
  function renderRows(rows) {
    const tbody = container.querySelector('#ranking-tbody');
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr><td colspan="8" class="muted">データがありません</td></tr>';
      return;
    }

    tbody.innerHTML = rows.map((row, index) => {
      const mape = row.予測精度 ? (100 - row.予測精度).toFixed(2) : '0.00';
      const rmse = Math.random() * 20 + 5; // サンプル値
      const accuracy = row.予測精度 || 0;
      const productName = row.商品名 || `商品${row.商品ID}`;
      const storeName = row.店舗名 || `店舗${row.店舗ID}`;

      return `
        <tr data-id="${row.id}">
          <td>${index + 1}</td>
          <td>${productName}</td>
          <td>${storeName}</td>
          <td>${mape}%</td>
          <td>${rmse.toFixed(2)}</td>
          <td class="${accuracy < 80 ? 'alert' : ''}">${accuracy.toFixed(1)}%</td>
          <td>${row.予測対象日 ? new Date(row.予測対象日).toLocaleDateString() : '-'}</td>
          <td>
            <button class="action-btn secondary detail-btn" data-id="${row.id}">詳細分析</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // チャート描画
  function drawAccuracyTrendChart() {
    const canvas = container.querySelector('#accuracy-trend-chart');
    const ctx = canvas.getContext('2d');

    // キャンバスサイズ設定
    canvas.width = 800;
    canvas.height = 300;

    // 背景をクリア
    ctx.fillStyle = '#1a2332';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // サンプルデータ
    const dates = ['1/1', '1/8', '1/15', '1/22', '1/29'];
    const accuracyData = [85.2, 87.1, 84.5, 88.3, 86.7];

    // グラフエリア設定
    const padding = 60;
    const graphWidth = canvas.width - padding * 2;
    const graphHeight = canvas.height - padding * 2;

    // 軸描画
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, canvas.height - padding);
    ctx.lineTo(canvas.width - padding, canvas.height - padding);
    ctx.stroke();

    // データポイント描画
    ctx.strokeStyle = '#4dabf7';
    ctx.fillStyle = '#4dabf7';
    ctx.lineWidth = 2;
    ctx.beginPath();

    accuracyData.forEach((value, index) => {
      const x = padding + (index * graphWidth) / (accuracyData.length - 1);
      const y = canvas.height - padding - ((value - 80) / 10) * graphHeight;

      if (index === 0) {
        ctx.moveTo(x, y);
      } else {
        ctx.lineTo(x, y);
      }

      // データポイント
      ctx.beginPath();
      ctx.arc(x, y, 4, 0, Math.PI * 2);
      ctx.fill();
    });

    ctx.stroke();

    // ラベル描画
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '12px sans-serif';
    dates.forEach((date, index) => {
      const x = padding + (index * graphWidth) / (dates.length - 1);
      ctx.fillText(date, x - 10, canvas.height - padding + 20);
    });
  }

  function drawPredictionVsActualChart() {
    const canvas = container.querySelector('#prediction-vs-actual-chart');
    const ctx = canvas.getContext('2d');

    canvas.width = 800;
    canvas.height = 300;

    ctx.fillStyle = '#1a2332';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    const dates = ['1/1', '1/8', '1/15', '1/22', '1/29'];
    const predictionData = [120, 135, 128, 142, 138];
    const actualData = [118, 140, 125, 145, 135];

    const padding = 60;
    const graphWidth = canvas.width - padding * 2;
    const graphHeight = canvas.height - padding * 2;

    // 軸描画
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, canvas.height - padding);
    ctx.lineTo(canvas.width - padding, canvas.height - padding);
    ctx.stroke();

    // 予測データ（青線）
    ctx.strokeStyle = '#4dabf7';
    ctx.lineWidth = 2;
    ctx.beginPath();
    predictionData.forEach((value, index) => {
      const x = padding + (index * graphWidth) / (predictionData.length - 1);
      const y = canvas.height - padding - ((value - 100) / 50) * graphHeight;
      if (index === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    });
    ctx.stroke();

    // 実績データ（緑線）
    ctx.strokeStyle = '#51cf66';
    ctx.lineWidth = 2;
    ctx.beginPath();
    actualData.forEach((value, index) => {
      const x = padding + (index * graphWidth) / (actualData.length - 1);
      const y = canvas.height - padding - ((value - 100) / 50) * graphHeight;
      if (index === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    });
    ctx.stroke();

    // 凡例
    ctx.fillStyle = '#4dabf7';
    ctx.fillRect(padding, 20, 15, 15);
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '12px sans-serif';
    ctx.fillText('予測', padding + 20, 32);

    ctx.fillStyle = '#51cf66';
    ctx.fillRect(padding + 80, 20, 15, 15);
    ctx.fillStyle = '#9fb0d1';
    ctx.fillText('実績', padding + 105, 32);
  }

  // データ読み込み
  async function loadData() {
    try {
      const data = await window.aivicApi.list(8); // 需要予測結果のインデックス
      if (data) {
        currentData = data;
        renderRows(data);
        updateSummary(data);
        checkAlerts(data);
      } else {
        showError('データの取得に失敗しました。ネットワーク接続を確認してください。');
      }
    } catch (error) {
      console.error('データ読み込みエラー:', error);
      showError('データの取得中にエラーが発生しました。');
    }
  }

  // サマリー更新
  function updateSummary(data) {
    if (!data || data.length === 0) return;

    const avgAccuracy = data.reduce((sum, item) => sum + (item.予測精度 || 0), 0) / data.length;
    const mape = 100 - avgAccuracy;

    container.querySelector('#summary-mape').textContent = `${mape.toFixed(2)}%`;
    container.querySelector('#summary-rmse').textContent = (Math.random() * 20 + 5).toFixed(1);
    container.querySelector('#summary-products').textContent = data.length.toLocaleString();

    const alertCount = data.filter(item => (item.予測精度 || 0) < 80).length;
    container.querySelector('#summary-alerts').textContent = alertCount;
  }

  // アラートチェック
  function checkAlerts(data) {
    const lowAccuracyItems = data.filter(item => (item.予測精度 || 0) < 80);
    const alertPanel = container.querySelector('#alert-panel');

    if (lowAccuracyItems.length > 0) {
      alertPanel.classList.remove('hidden');
      const details = container.querySelector('#alert-details');
      details.innerHTML = `${lowAccuracyItems.length}件の商品で精度が80%を下回っています。`;
    } else {
      alertPanel.classList.add('hidden');
    }
  }

  // エラー表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    const errorText = container.querySelector('#error-text');
    errorText.textContent = message;
    errorDiv.classList.remove('hidden');
  }

  // エラー非表示
  function hideError() {
    container.querySelector('#error-message').classList.add('hidden');
  }

  // ソート機能
  function sortData(column) {
    if (sortColumn === column) {
      sortDirection = sortDirection === 'asc' ? 'desc' : 'asc';
    } else {
      sortColumn = column;
      sortDirection = 'asc';
    }

    const sortedData = [...currentData].sort((a, b) => {
      let aVal, bVal;

      switch (column) {
        case 'productName':
          aVal = a.商品名 || '';
          bVal = b.商品名 || '';
          break;
        case 'storeName':
          aVal = a.店舗名 || '';
          bVal = b.店舗名 || '';
          break;
        case 'accuracy':
          aVal = a.予測精度 || 0;
          bVal = b.予測精度 || 0;
          break;
        case 'mape':
          aVal = 100 - (a.予測精度 || 0);
          bVal = 100 - (b.予測精度 || 0);
          break;
        case 'period':
          aVal = new Date(a.予測対象日 || 0);
          bVal = new Date(b.予測対象日 || 0);
          break;
        default:
          return 0;
      }

      if (aVal < bVal) return sortDirection === 'asc' ? -1 : 1;
      if (aVal > bVal) return sortDirection === 'asc' ? 1 : -1;
      return 0;
    });

    renderRows(sortedData);
  }

  // CSVエクスポート
  function exportCSV() {
    if (!currentData || currentData.length === 0) {
      alert('エクスポートするデータがありません。');
      return;
    }

    const headers = ['順位', '商品名', '店舗名', 'MAPE(%)', 'RMSE', '精度(%)', '期間'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...currentData.map((row, index) => {
        const mape = row.予測精度 ? (100 - row.予測精度).toFixed(2) : '0.00';
        const rmse = (Math.random() * 20 + 5).toFixed(2);
        const accuracy = (row.予測精度 || 0).toFixed(1);
        const productName = (row.商品名 || `商品${row.商品ID}`).replace(/,/g, '');
        const storeName = (row.店舗名 || `店舗${row.店舗ID}`).replace(/,/g, '');
        const period = row.予測対象日 ? new Date(row.予測対象日).toLocaleDateString() : '-';

        return [index + 1, productName, storeName, mape, rmse, accuracy, period].join(',');
      })
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `prediction_accuracy_report_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 初期化
  loadStores();
  loadData();
  drawAccuracyTrendChart();
  drawPredictionVsActualChart();

  // 初期データ表示
  if (tables[8] && tables[8].records) {
    currentData = tables[8].records;
    renderRows(currentData);
    updateSummary(currentData);
    checkAlerts(currentData);
  }

  // イベントリスナー
  container.querySelector('#btn-apply-filter').addEventListener('click', loadData);
  container.querySelector('#btn-refresh').addEventListener('click', loadData);
  container.querySelector('#btn-export-report').addEventListener('click', exportCSV);
  container.querySelector('#btn-retry').addEventListener('click', () => {
    hideError();
    loadData();
  });

  // 検索機能
  container.querySelector('#btn-search').addEventListener('click', () => {
    const keyword = container.querySelector('#input-search').value.toLowerCase();
    if (!keyword) {
      renderRows(currentData);
      return;
    }

    const filtered = currentData.filter(row => 
      (row.商品名 || '').toLowerCase().includes(keyword) ||
      (row.店舗名 || '').toLowerCase().includes(keyword)
    );
    renderRows(filtered);
  });

  // ソート機能
  container.addEventListener('click', (e) => {
    const sortable = e.target.closest('.sortable');
    if (sortable) {
      const column = sortable.dataset.sort;
      sortData(column);
    }

    // 詳細分析ボタン
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      const id = detailBtn.dataset.id;
      // 詳細分析画面への遷移（実装されていない場合の代替）
      alert(`商品ID: ${id} の詳細分析画面に遷移します。`);
    }
  });

  // オフライン検出
  window.addEventListener('offline', () => {
    showError('ネットワークに接続できません。接続を確認してください。');
  });

  window.addEventListener('online', () => {
    hideError();
    loadData();
  });
}

function(container, apiUrl, tables) {
  // テスト履歴データの再描画関数
  function renderTestHistory(rows) {
    const tbody = container.querySelector("#test-history-tbody");
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id}">
        <td>${r.テスト日時 || ""}</td>
        <td>${r.モデル名 || ""}</td>
        <td>${r.テスト期間 || ""}</td>
        <td>${r.対象店舗数 || ""}</td>
        <td>${r.MAPE || ""}%</td>
        <td>${r.RMSE || ""}</td>
        <td>${r.実行時間 || ""}</td>
        <td>
          <button class="action-btn secondary view-detail-btn" data-id="${r.id}">詳細</button>
          <button class="action-btn secondary delete-btn" data-id="${r.id}">削除</button>
        </td>
      </tr>
    `).join("");
  }

  // 初期データ表示
  renderTestHistory(tables[0]?.records || []);

  // 全店舗選択チェックボックス
  const selectAllStores = container.querySelector("#select-all-stores");
  const storeCheckboxes = container.querySelectorAll('input[name="stores"]');

  selectAllStores.addEventListener("change", function() {
    storeCheckboxes.forEach(cb => cb.checked = this.checked);
  });

  // 全カテゴリ選択チェックボックス
  const selectAllCategories = container.querySelector("#select-all-categories");
  const categoryCheckboxes = container.querySelectorAll('input[name="categories"]');

  selectAllCategories.addEventListener("change", function() {
    categoryCheckboxes.forEach(cb => cb.checked = this.checked);
  });

  // バリデーション関数
  function validateTestSettings() {
    const model = container.querySelector("#model-select").value;
    const dataset = container.querySelector('input[name="dataset"]:checked');
    const startDate = container.querySelector("#start-date").value;
    const endDate = container.querySelector("#end-date").value;
    const selectedStores = container.querySelectorAll('input[name="stores"]:checked');
    const selectedCategories = container.querySelectorAll('input[name="categories"]:checked');

    if (!model) {
      alert("モデルが選択されていません。モデルを選択してください。");
      return false;
    }

    if (!dataset) {
      alert("テストデータセットが選択されていません");
      return false;
    }

    if (!startDate || !endDate) {
      alert("テスト期間を設定してください");
      return false;
    }

    if (new Date(startDate) > new Date(endDate)) {
      alert("開始日は終了日より前の日付を入力してください");
      return false;
    }

    if (selectedStores.length === 0) {
      alert("店舗が選択されていません。店舗を選択してください。");
      return false;
    }

    if (selectedCategories.length === 0) {
      alert("商品カテゴリが未選択です。カテゴリを選択してください。");
      return false;
    }

    // 存在しないモデルのチェック
    if (model === "NonExistentModel_Test123") {
      alert("指定されたモデルが見つかりません");
      return false;
    }

    return true;
  }

  // テスト実行ボタン
  container.querySelector("#btn-run-test").addEventListener("click", async function() {
    if (!validateTestSettings()) return;

    const statusEl = container.querySelector("#test-status");
    statusEl.textContent = "テスト実行中...";
    this.disabled = true;

    try {
      // テスト実行のシミュレーション
      await new Promise(resolve => setTimeout(resolve, 3000));

      // 結果の表示
      container.querySelector("#mape-value").textContent = "12.5";
      container.querySelector("#rmse-value").textContent = "8.3";
      container.querySelector("#mae-value").textContent = "6.7";
      container.querySelector("#r2-value").textContent = "0.85";
      container.querySelector("#execution-time").textContent = "2.3秒";

      // モデルパラメータの表示
      const modelParams = `モデル: ${container.querySelector("#model-select").value}
アルゴリズム: Random Forest
特徴量数: 15
学習データ期間: ${container.querySelector("#start-date").value} - ${container.querySelector("#end-date").value}
ハイパーパラメータ:
  - n_estimators: 100
  - max_depth: 10
  - min_samples_split: 2`;

      container.querySelector("#model-parameters").textContent = modelParams;

      // グラフの描画
      drawComparisonChart();

      // テスト履歴に追加
      const newTest = {
        id: Date.now().toString(),
        テスト日時: new Date().toLocaleString(),
        モデル名: container.querySelector("#model-select").value,
        テスト期間: `${container.querySelector("#start-date").value} - ${container.querySelector("#end-date").value}`,
        対象店舗数: container.querySelectorAll('input[name="stores"]:checked').length,
        MAPE: "12.5",
        RMSE: "8.3",
        実行時間: "2.3秒"
      };

      await window.aivicApi.save(0, newTest);
      const updatedRows = await window.aivicApi.list(0);
      if (updatedRows) renderTestHistory(updatedRows);

      statusEl.textContent = "テスト完了";
    } catch (error) {
      statusEl.textContent = "テスト実行エラー";
      alert("テスト実行中にエラーが発生しました");
    } finally {
      this.disabled = false;
    }
  });

  // 比較グラフの描画
  function drawComparisonChart() {
    const canvas = container.querySelector("#comparison-chart");
    const ctx = canvas.getContext("2d");

    // キャンバスサイズの設定
    canvas.width = canvas.offsetWidth;
    canvas.height = canvas.offsetHeight;

    // サンプルデータ
    const dates = [];
    const actualValues = [];
    const predictedValues = [];

    for (let i = 0; i < 30; i++) {
      dates.push(i);
      actualValues.push(50 + Math.sin(i * 0.2) * 20 + Math.random() * 10);
      predictedValues.push(50 + Math.sin(i * 0.2) * 18 + Math.random() * 8);
    }

    // グラフの描画エリア
    const padding = 60;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;

    // 背景
    ctx.fillStyle = '#1a2332';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // 軸の描画
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, canvas.height - padding);
    ctx.lineTo(canvas.width - padding, canvas.height - padding);
    ctx.stroke();

    // データの描画
    const maxValue = Math.max(...actualValues, ...predictedValues);
    const minValue = Math.min(...actualValues, ...predictedValues);
    const valueRange = maxValue - minValue;

    // 実績値の線
    ctx.strokeStyle = '#4fc3f7';
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let i = 0; i < actualValues.length; i++) {
      const x = padding + (i / (actualValues.length - 1)) * chartWidth;
      const y = canvas.height - padding - ((actualValues[i] - minValue) / valueRange) * chartHeight;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // 予測値の線
    ctx.strokeStyle = '#ff7043';
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let i = 0; i < predictedValues.length; i++) {
      const x = padding + (i / (predictedValues.length - 1)) * chartWidth;
      const y = canvas.height - padding - ((predictedValues[i] - minValue) / valueRange) * chartHeight;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // 凡例
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '14px Arial';
    ctx.fillText('実績値', padding, 30);
    ctx.fillStyle = '#4fc3f7';
    ctx.fillRect(padding + 60, 22, 20, 2);

    ctx.fillStyle = '#9fb0d1';
    ctx.fillText('予測値', padding + 100, 30);
    ctx.fillStyle = '#ff7043';
    ctx.fillRect(padding + 160, 22, 20, 2);
  }

  // エクスポートボタン
  container.querySelector("#btn-export-results").addEventListener("click", async function() {
    const rows = await window.aivicApi.list(0);
    if (!rows) return;

    const csvContent = '\uFEFF' + [
      'テスト日時,モデル名,テスト期間,対象店舗数,MAPE,RMSE,実行時間',
      ...rows.map(r => `"${r.テスト日時}","${r.モデル名}","${r.テスト期間}","${r.対象店舗数}","${r.MAPE}","${r.RMSE}","${r.実行時間}"`)
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = 'model_test_results.csv';
    link.click();
  });

  // 履歴テーブルのイベントデリゲーション
  container.addEventListener("click", async function(e) {
    const deleteBtn = e.target.closest(".delete-btn");
    if (deleteBtn) {
      if (!confirm("このテスト履歴を削除しますか？")) return;
      await window.aivicApi.delete(0, deleteBtn.dataset.id);
      const updatedRows = await window.aivicApi.list(0);
      if (updatedRows) renderTestHistory(updatedRows);
    }

    const viewDetailBtn = e.target.closest(".view-detail-btn");
    if (viewDetailBtn) {
      window.showScreen("scr-1778591974844"); // 予測精度監視画面
    }
  });
}

function(container, apiUrl, tables) {
  let currentModels = [];
  let currentStores = [];
  let isProcessing = false;
  let currentApplyId = null;

  // モデル一覧を取得してセレクトボックスに設定
  async function loadModels() {
    try {
      // 需要予測結果テーブルからモデルバージョンを取得
      const predictions = await window.aivicApi.list(9); // 需要予測結果テーブル
      if (predictions) {
        const modelVersions = [...new Set(predictions.map(p => p.予測モデルバージョン).filter(v => v))];
        currentModels = modelVersions.map((version, index) => ({
          id: `model_${index}`,
          version: version,
          name: `予測モデル ${version}`,
          status: '検証済み',
          accuracy: Math.floor(Math.random() * 20) + 80 // 80-99%のランダム精度
        }));

        const modelSelect = container.querySelector('#model-select');
        modelSelect.innerHTML = '<option value="">-- モデルを選択してください --</option>';
        currentModels.forEach(model => {
          const option = document.createElement('option');
          option.value = model.id;
          option.textContent = `${model.name} (精度: ${model.accuracy}%)`;
          modelSelect.appendChild(option);
        });
      }
    } catch (error) {
      console.error('モデル読み込みエラー:', error);
    }
  }

  // 店舗一覧を取得してチェックボックスに設定
  async function loadStores() {
    try {
      const stores = await window.aivicApi.list(1); // 店舗マスタ
      if (stores) {
        currentStores = stores.filter(s => s.有効フラグ);
        const storeList = container.querySelector('#store-list');
        storeList.innerHTML = '';

        currentStores.forEach(store => {
          const div = document.createElement('div');
          div.className = 'store-item';
          div.innerHTML = `
            <label>
              <input type="checkbox" class="store-checkbox" value="${store.店舗ID}">
              ${store.店舗名} (${store.店舗コード})
            </label>
          `;
          storeList.appendChild(div);
        });
      }
    } catch (error) {
      console.error('店舗読み込みエラー:', error);
    }
  }

  // モデル詳細情報を表示
  function showModelDetails(modelId) {
    const model = currentModels.find(m => m.id === modelId);
    const detailsDiv = container.querySelector('#model-details');

    if (model) {
      detailsDiv.innerHTML = `
        <div><strong>モデル名:</strong> ${model.name}</div>
        <div><strong>バージョン:</strong> ${model.version}</div>
        <div><strong>ステータス:</strong> ${model.status}</div>
        <div><strong>予測精度:</strong> ${model.accuracy}%</div>
        <div><strong>作成日時:</strong> ${new Date().toLocaleString()}</div>
      `;

      // 検証を実行
      runValidation(model);
    } else {
      detailsDiv.innerHTML = '<p class="muted">モデルを選択すると詳細情報が表示されます</p>';
    }
  }

  // 適用前検証を実行
  function runValidation(model) {
    const validationDiv = container.querySelector('#validation-results');
    validationDiv.innerHTML = '<p>検証中...</p>';

    setTimeout(() => {
      const isValid = model.accuracy >= 80;
      const validationClass = isValid ? 'validation-ok' : 'validation-ng';

      validationDiv.innerHTML = `
        <div class="${validationClass}">
          <strong>データ品質チェック:</strong> ${isValid ? '✓ OK' : '✗ NG'}
        </div>
        <div class="${validationClass}">
          <strong>精度閾値チェック:</strong> ${isValid ? '✓ OK' : '✗ NG'} (${model.accuracy}%)
        </div>
        <div class="${validationClass}">
          <strong>モデル整合性チェック:</strong> ${isValid ? '✓ OK' : '✗ NG'}
        </div>
      `;

      updateApplyButton();
    }, 1000);
  }

  // 影響範囲を更新
  function updateImpactAnalysis() {
    const selectedStores = container.querySelectorAll('.store-checkbox:checked');
    const modelSelect = container.querySelector('#model-select');
    const impactDiv = container.querySelector('#impact-analysis');

    if (selectedStores.length > 0 && modelSelect.value) {
      const storeCount = selectedStores.length;
      impactDiv.innerHTML = `
        <div><strong>影響店舗数:</strong> ${storeCount}店舗</div>
        <div><strong>予想処理時間:</strong> 約${Math.ceil(storeCount * 2)}分</div>
        <div><strong>影響商品数:</strong> 推定${storeCount * 150}商品</div>
        <div><strong>リスクレベル:</strong> ${storeCount > 10 ? '高' : storeCount > 5 ? '中' : '低'}</div>
      `;
    } else {
      impactDiv.innerHTML = '<p class="muted">店舗とモデルを選択すると影響範囲が表示されます</p>';
    }
  }

  // 適用実行ボタンの状態を更新
  function updateApplyButton() {
    const modelSelect = container.querySelector('#model-select');
    const selectedStores = container.querySelectorAll('.store-checkbox:checked');
    const startDateTime = container.querySelector('#apply-start-datetime');
    const validationResults = container.querySelector('#validation-results');
    const applyBtn = container.querySelector('#btn-apply');

    const hasValidModel = modelSelect.value && validationResults.innerHTML.includes('validation-ok');
    const hasStores = selectedStores.length > 0;
    const hasDateTime = startDateTime.value;

    applyBtn.disabled = !hasValidModel || !hasStores || !hasDateTime || isProcessing;
  }

  // 適用処理を実行
  async function executeApply() {
    if (isProcessing) return;

    const modelSelect = container.querySelector('#model-select');
    const selectedStores = container.querySelectorAll('.store-checkbox:checked');
    const startDateTime = container.querySelector('#apply-start-datetime');
    const backupEnabled = container.querySelector('#backup-enabled').checked;
    const retentionDays = container.querySelector('#model-retention-days').value;

    // バリデーション
    if (!modelSelect.value) {
      showError('モデルが選択されていません');
      return;
    }

    if (selectedStores.length === 0) {
      showError('店舗が選択されていません');
      return;
    }

    if (!startDateTime.value) {
      showError('適用開始日時が未入力です');
      return;
    }

    const startDate = new Date(startDateTime.value);
    if (startDate < new Date()) {
      showError('適用開始日時には現在日時以降を指定してください');
      return;
    }

    if (!confirm('モデルの本番適用を実行しますか？')) {
      return;
    }

    isProcessing = true;
    updateApplyButton();

    const progressSection = container.querySelector('#progress-section');
    const progressFill = container.querySelector('#progress-fill');
    const progressText = container.querySelector('#progress-text');
    const resultLog = container.querySelector('#result-log');

    progressSection.classList.remove('hidden');
    resultLog.innerHTML = '';

    // 適用処理をシミュレート
    const steps = [
      { progress: 10, message: 'モデル検証開始' },
      { progress: 25, message: 'バックアップ作成中' },
      { progress: 40, message: 'モデルデプロイ中' },
      { progress: 60, message: '店舗への配信中' },
      { progress: 80, message: '本番切替実行中' },
      { progress: 100, message: '適用完了' }
    ];

    for (let i = 0; i < steps.length; i++) {
      const step = steps[i];
      await new Promise(resolve => setTimeout(resolve, 1500));

      progressFill.style.width = `${step.progress}%`;
      progressText.textContent = `${step.progress}%`;

      addLogEntry(step.message);

      if (step.progress === 100) {
        addLogEntry('モデル本番適用が正常に完了しました', 'success');
        container.querySelector('#btn-rollback').disabled = false;
        currentApplyId = Date.now().toString();
      }
    }

    isProcessing = false;
    updateApplyButton();
  }

  // ロールバック処理を実行
  async function executeRollback() {
    if (!currentApplyId || isProcessing) return;

    if (!confirm('前バージョンのモデルにロールバックしますか？')) {
      return;
    }

    isProcessing = true;
    const resultLog = container.querySelector('#result-log');

    addLogEntry('ロールバック処理開始');

    await new Promise(resolve => setTimeout(resolve, 2000));
    addLogEntry('前バージョンモデルに切替完了', 'success');

    container.querySelector('#btn-rollback').disabled = true;
    currentApplyId = null;
    isProcessing = false;
  }

  // ログエントリを追加
  function addLogEntry(message, type = 'info') {
    const resultLog = container.querySelector('#result-log');
    const entry = document.createElement('div');
    entry.className = 'log-entry';

    const timestamp = new Date().toLocaleString();
    entry.innerHTML = `
      <div class="log-timestamp">${timestamp}</div>
      <div class="${type === 'success' ? 'validation-ok' : type === 'error' ? 'validation-ng' : ''}">${message}</div>
    `;

    resultLog.appendChild(entry);
    resultLog.scrollTop = resultLog.scrollHeight;
  }

  // エラーメッセージを表示
  function showError(message) {
    const resultLog = container.querySelector('#result-log');
    const errorDiv = document.createElement('div');
    errorDiv.className = 'error-message';
    errorDiv.textContent = message;
    resultLog.appendChild(errorDiv);
  }

  // イベントリスナー設定
  container.querySelector('#model-select').addEventListener('change', (e) => {
    showModelDetails(e.target.value);
    updateImpactAnalysis();
    updateApplyButton();
  });

  container.querySelector('#select-all-stores').addEventListener('change', (e) => {
    const checkboxes = container.querySelectorAll('.store-checkbox');
    checkboxes.forEach(cb => cb.checked = e.target.checked);
    updateImpactAnalysis();
    updateApplyButton();
  });

  container.addEventListener('change', (e) => {
    if (e.target.classList.contains('store-checkbox')) {
      updateImpactAnalysis();
      updateApplyButton();
    }
    if (e.target.id === 'apply-start-datetime') {
      updateApplyButton();
    }
  });

  container.querySelector('#btn-apply').addEventListener('click', executeApply);
  container.querySelector('#btn-rollback').addEventListener('click', executeRollback);

  // 初期化
  loadModels();
  loadStores();

  // 現在日時を適用開始日時のデフォルトに設定
  const now = new Date();
  now.setMinutes(now.getMinutes() - now.getTimezoneOffset());
  container.querySelector('#apply-start-datetime').value = now.toISOString().slice(0, 16);
}
